struct ClothOriginalKey {
    std::uintptr_t tune{};
    unsigned int groupIndex{};
    bool operator==(const ClothOriginalKey& other) const {
        return tune == other.tune && groupIndex == other.groupIndex;
    }
};
struct ClothOriginalKeyHash {
    std::size_t operator()(const ClothOriginalKey& key) const noexcept {
        std::size_t h = std::hash<std::uintptr_t>{}(key.tune);
        h ^= std::hash<unsigned int>{}(key.groupIndex) + 0x9e3779b9u + (h << 6) + (h >> 2);
        return h;
    }
};
