    std::uint8_t numPixelInstanceParams{};
    std::uint8_t firstVertexInstanceParam{};
    std::uint8_t numVertexInstanceParams{};
    std::uint8_t firstPixelExtendedInstanceParam{};
    std::uint8_t numPixelExtendedInstanceParams{};
    std::uint8_t firstVertexExtendedInstanceParam{};
