// Edits waiting for the game thread, in order (a named parameter writes several constants at once: each is kept;
// a newer value for the same constant replaces the older one).
std::vector<PendingMaterialEdit> g_pendingMaterialEdits;
std::atomic_bool g_hasPendingMaterialEdit{false};
constexpr std::size_t kMaxPendingMaterialEdits = 512;

void QueuePendingMaterialEditLocked(const PendingMaterialEdit& edit) {
    if (edit.type == MaterialEditType::Constant)
        for (auto& queued : g_pendingMaterialEdits)
            if (queued.type == MaterialEditType::Constant && queued.material == edit.material &&
                queued.passIndex == edit.passIndex && queued.stage == edit.stage && queued.index == edit.index) {
                const bool finalize = queued.finalize || edit.finalize;
                queued = edit;
                queued.finalize = finalize;
                return;
            }
    if (g_pendingMaterialEdits.size() >= kMaxPendingMaterialEdits) g_pendingMaterialEdits.erase(g_pendingMaterialEdits.begin());
    g_pendingMaterialEdits.push_back(edit);
}
