struct WeatherCatalogRuntime {
    std::uintptr_t globalWeather{};
    const GlobalWeatherTypeLite* weatherTypes{};
    unsigned int weatherTypeCount{};
    const GlobalTimeOfDayTypeLite* timeOfDayTypes{};
    unsigned int timeOfDayTypeCount{};
    int rainIndex{-1};
    int snowIndex{-1};
    int nightIndex{-1};
    int dawnIndex{-1};
    int dayIndex{-1};
    int duskIndex{-1};

    bool HasWeatherControls() const {
        return rainIndex >= 0 && snowIndex >= 0 &&
               static_cast<unsigned int>(rainIndex) < weatherTypeCount &&
               static_cast<unsigned int>(snowIndex) < weatherTypeCount;
    }

    bool HasCanonicalTimeOfDay() const {
        return nightIndex >= 0 && dawnIndex >= 0 && dayIndex >= 0 && duskIndex >= 0 &&
               static_cast<unsigned int>(nightIndex) < timeOfDayTypeCount &&
               static_cast<unsigned int>(dawnIndex) < timeOfDayTypeCount &&
               static_cast<unsigned int>(dayIndex) < timeOfDayTypeCount &&
               static_cast<unsigned int>(duskIndex) < timeOfDayTypeCount;
    }
};

