std::uint64_t QpcNow() {
    LARGE_INTEGER value{};
    QueryPerformanceCounter(&value);
    return static_cast<std::uint64_t>(value.QuadPart);
}

std::uint64_t QpcFrequency() {
    static const std::uint64_t frequency = [] {
        LARGE_INTEGER value{};
        QueryPerformanceFrequency(&value);
        return static_cast<std::uint64_t>(value.QuadPart > 0 ? value.QuadPart : 1);
    }();
    return frequency;
}

double QpcSeconds(std::uint64_t ticks) {
    return static_cast<double>(ticks) / static_cast<double>(QpcFrequency());
}

void AtomicMax(std::atomic<std::uint64_t>& destination, std::uint64_t value);

const char* LoadingWaitApiName(LoadingWaitApi api) {
    switch (api) {
    case LoadingWaitApi::Sleep: return "Sleep";
    case LoadingWaitApi::SleepEx: return "SleepEx";
    case LoadingWaitApi::WaitForSingleObject: return "WaitForSingleObject";
    case LoadingWaitApi::WaitForSingleObjectEx: return "WaitForSingleObjectEx";
    case LoadingWaitApi::WaitForMultipleObjects: return "WaitForMultipleObjects";
    case LoadingWaitApi::WaitForMultipleObjectsEx: return "WaitForMultipleObjectsEx";
    case LoadingWaitApi::WaitMessage: return "WaitMessage";
    default: return "Unknown";
    }
}

std::uint64_t ReturnAddressToGameRva(void* returnAddress) {
    const std::uintptr_t base = GameBuild::Base();
    if (!base || !returnAddress)
        return 0;
    const auto* dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(base);
    if (dos->e_magic != IMAGE_DOS_SIGNATURE)
        return 0;
    const auto* nt = reinterpret_cast<const IMAGE_NT_HEADERS64*>(base + static_cast<std::uintptr_t>(dos->e_lfanew));
    if (nt->Signature != IMAGE_NT_SIGNATURE)
        return 0;
    const std::uintptr_t address = reinterpret_cast<std::uintptr_t>(returnAddress);
    const std::uintptr_t end = base + static_cast<std::uintptr_t>(nt->OptionalHeader.SizeOfImage);
    return address >= base && address < end ? static_cast<std::uint64_t>(address - base) : 0;
}

bool ShouldProfileLoadingThreadWait() {
    if (!g_loadingProfileActive.load(std::memory_order_acquire))
        return false;
    const DWORD loadingThread = g_loadingThreadId.load(std::memory_order_relaxed);
    return loadingThread != 0 && GetCurrentThreadId() == loadingThread;
}

void RecordLoadingWait(LoadingWaitApi api, void* returnAddress, std::uint64_t begin,
                       std::uint64_t end, DWORD requestedTimeout, bool hasWaitResult, DWORD waitResult) {
    const std::uint64_t elapsed = end >= begin ? end - begin : 0;
    const std::size_t apiIndex = static_cast<std::size_t>(api);
    if (apiIndex >= kLoadingWaitApiCount)
        return;

    g_loadingWaitCalls.fetch_add(1, std::memory_order_relaxed);
    g_loadingWaitTicks.fetch_add(elapsed, std::memory_order_relaxed);
    AtomicMax(g_loadingWaitMaxTicks, elapsed);
    g_loadingWaitApiCalls[apiIndex].fetch_add(1, std::memory_order_relaxed);
    g_loadingWaitApiTicks[apiIndex].fetch_add(elapsed, std::memory_order_relaxed);
    AtomicMax(g_loadingWaitApiMaxTicks[apiIndex], elapsed);

    if (requestedTimeout == INFINITE)
        g_loadingWaitInfiniteCalls.fetch_add(1, std::memory_order_relaxed);
    else if (requestedTimeout == 0)
        g_loadingWaitZeroTimeoutCalls.fetch_add(1, std::memory_order_relaxed);
    else
        g_loadingWaitFiniteTimeoutCalls.fetch_add(1, std::memory_order_relaxed);

    if (hasWaitResult && waitResult == WAIT_TIMEOUT) {
        g_loadingWaitTimeoutResults.fetch_add(1, std::memory_order_relaxed);
        g_loadingWaitApiTimeoutResults[apiIndex].fetch_add(1, std::memory_order_relaxed);
    }

    const std::uint64_t callerRva = ReturnAddressToGameRva(returnAddress);
    for (std::size_t i = 0; i < g_loadingWaitSiteCount; ++i) {
        auto& site = g_loadingWaitSites[i];
        if (site.api == api && site.callerRva == callerRva) {
            ++site.calls;
            site.ticks += elapsed;
            if (elapsed > site.maxTicks)
                site.maxTicks = elapsed;
            return;
        }
    }
    if (g_loadingWaitSiteCount < kLoadingWaitRuntimeSiteCapacity) {
        auto& site = g_loadingWaitSites[g_loadingWaitSiteCount++];
        site.callerRva = callerRva;
        site.calls = 1;
        site.ticks = elapsed;
        site.maxTicks = elapsed;
        site.api = api;
    }
}

void AtomicMax(std::atomic<std::uint64_t>& destination, std::uint64_t value) {
    std::uint64_t current = destination.load(std::memory_order_relaxed);
    while (current < value &&
           !destination.compare_exchange_weak(current, value,
                                              std::memory_order_relaxed,
                                              std::memory_order_relaxed)) {
    }
}

std::uint64_t FileTime100ns(const FILETIME& value) {
    ULARGE_INTEGER combined{};
    combined.LowPart = value.dwLowDateTime;
    combined.HighPart = value.dwHighDateTime;
    return combined.QuadPart;
}

void CaptureProcessTimes(std::uint64_t& kernel100ns, std::uint64_t& user100ns) {
    FILETIME creation{}, exit{}, kernel{}, user{};
    if (GetProcessTimes(GetCurrentProcess(), &creation, &exit, &kernel, &user)) {
        kernel100ns = FileTime100ns(kernel);
        user100ns = FileTime100ns(user);
    } else {
        kernel100ns = 0;
        user100ns = 0;
    }
}

void CaptureCurrentThreadTimes(std::uint64_t& kernel100ns, std::uint64_t& user100ns) {
    FILETIME creation{}, exit{}, kernel{}, user{};
    if (GetThreadTimes(GetCurrentThread(), &creation, &exit, &kernel, &user)) {
        kernel100ns = FileTime100ns(kernel);
        user100ns = FileTime100ns(user);
    } else {
        kernel100ns = 0;
        user100ns = 0;
    }
}

std::uint64_t ThreadCpuDelta100ns(std::uint64_t kernelBefore, std::uint64_t userBefore) {
    std::uint64_t kernelAfter = 0, userAfter = 0;
    CaptureCurrentThreadTimes(kernelAfter, userAfter);
    const std::uint64_t k = kernelAfter >= kernelBefore ? kernelAfter - kernelBefore : 0;
    const std::uint64_t u = userAfter >= userBefore ? userAfter - userBefore : 0;
    return k + u;
}

void AtomicMinInt(std::atomic<int>& destination, int value) {
    int current = destination.load(std::memory_order_relaxed);
    while (current > value &&
           !destination.compare_exchange_weak(current, value,
                                              std::memory_order_relaxed,
                                              std::memory_order_relaxed)) {
    }
}

void AtomicMaxInt(std::atomic<int>& destination, int value) {
    int current = destination.load(std::memory_order_relaxed);
    while (current < value &&
           !destination.compare_exchange_weak(current, value,
                                              std::memory_order_relaxed,
                                              std::memory_order_relaxed)) {
    }
}

