    profile.win32ReadRequestedBytes = g_loadingReadRequestedBytes.load(std::memory_order_relaxed);
    profile.win32ReadCompletedBytes = g_loadingReadCompletedBytes.load(std::memory_order_relaxed);
    profile.win32ReadAggregateSeconds = QpcSeconds(g_loadingReadTicks.load(std::memory_order_relaxed));
    profile.win32ReadMaxMs = QpcSeconds(g_loadingReadMaxTicks.load(std::memory_order_relaxed)) * 1000.0;
