bool __fastcall HookCommonRenderDeviceBeginFrame(void* self, float frameDelta) {
    if (!g_originalRenderDeviceBeginFrame)
        return false;

    if (g_materialEditorActive.load(std::memory_order_relaxed))
        g_materialRenderFrame.fetch_add(1, std::memory_order_relaxed);

    
    
    
    

    const bool loadingActive = g_loadingProfileActive.load(std::memory_order_acquire);
    const bool aggressive =
        loadingActive &&
        g_loadingFastModeSession.load(std::memory_order_relaxed) &&
        g_loadingAggressiveRendererSession.load(std::memory_order_relaxed) &&
        FastLoadingPhase();

    if (loadingActive)
        g_fastLoadingRendererBeginFrameCalls.fetch_add(1, std::memory_order_relaxed);

    if (self) {
        
        
        auto* bytes = reinterpret_cast<std::uint8_t*>(self);
        int* desired = reinterpret_cast<int*>(bytes + kRenderDeviceMulticoreModeSettingOffset);
        int* current = reinterpret_cast<int*>(bytes + kRenderDeviceMulticoreModeOffset);

        if (aggressive) {
            std::uintptr_t expectedDevice = 0;
            const std::uintptr_t selfValue = reinterpret_cast<std::uintptr_t>(self);
            if (g_fastLoadingRendererDevice.compare_exchange_strong(
                    expectedDevice, selfValue, std::memory_order_relaxed, std::memory_order_relaxed)) {
                g_fastLoadingRendererOriginalSetting.store(*desired, std::memory_order_relaxed);
                g_fastLoadingRendererOriginalMode.store(*current, std::memory_order_relaxed);
            }

            if (g_fastLoadingRendererDevice.load(std::memory_order_relaxed) == selfValue &&
                *desired != kRenderMulticoreDisabled) {
                *desired = kRenderMulticoreDisabled;
                g_fastLoadingRendererOverrideWrites.fetch_add(1, std::memory_order_relaxed);
            }
        } else if (g_fastLoadingRendererDevice.load(std::memory_order_relaxed) ==
                   reinterpret_cast<std::uintptr_t>(self)) {
            const int originalSetting = g_fastLoadingRendererOriginalSetting.load(std::memory_order_relaxed);
            if (originalSetting >= 0 && *desired != originalSetting) {
                *desired = originalSetting;
                g_fastLoadingRendererRestoreWrites.fetch_add(1, std::memory_order_relaxed);
            }
        }

        g_fastLoadingRendererLastSetting.store(*desired, std::memory_order_relaxed);
        g_fastLoadingRendererLastMode.store(*current, std::memory_order_relaxed);
    }

    const bool result = g_originalRenderDeviceBeginFrame(self, frameDelta);

    if (self) {
        auto* bytes = reinterpret_cast<std::uint8_t*>(self);
        g_fastLoadingRendererLastSetting.store(
            *reinterpret_cast<int*>(bytes + kRenderDeviceMulticoreModeSettingOffset),
            std::memory_order_relaxed);
        g_fastLoadingRendererLastMode.store(
            *reinterpret_cast<int*>(bytes + kRenderDeviceMulticoreModeOffset),
            std::memory_order_relaxed);
    }
    return result;
}

