// Per-tick section timings for the dual-wield frame probe (game thread; only while dual wield is on).
struct DualTickSection {
    const char* name;
    double ms;
};
DualTickSection g_dualTickSections[32]{};
int g_dualTickSectionCount = 0;
bool g_dualTickProbe = false;

// v0.9.287 frame-time probe: every section's time summed over the 30 s summary window (game thread).
struct FrameSectionTotal {
    const char* name;
    double sumMs;
    double maxMs;
    unsigned slowTicks;  // ticks where the section took 4 ms or more
};
FrameSectionTotal g_frameSectionTotals[48]{};
int g_frameSectionTotalCount = 0;

// (v0.9.602) a viewer (the Model Viewer, the Cutscene Viewer playing) was in use during the summary's window: the 30 s
// summary is written even when the window was smooth (the viewers' frame time measured, its sections listed)
bool g_frameWindowViewer = false;

void AddFrameSectionTotal(const char* name, double ms) {
    int i = 0;
    while (i < g_frameSectionTotalCount && g_frameSectionTotals[i].name != name) ++i;
    if (i == g_frameSectionTotalCount) {
        if (i >= 48) return;
        g_frameSectionTotals[g_frameSectionTotalCount++] = {name, 0.0, 0.0, 0u};
    }
    FrameSectionTotal& t = g_frameSectionTotals[i];
    t.sumMs += ms;
    if (ms > t.maxMs) t.maxMs = ms;
    if (ms >= 4.0) ++t.slowTicks;
}

struct DualScopedSection {
    const char* name;
    double start;
    explicit DualScopedSection(const char* sectionName)
        : name(sectionName), start(g_dualTickProbe ? DualDiagNowMs() : 0.0) {}
    ~DualScopedSection() {
        if (!g_dualTickProbe) return;
        const double ms = DualDiagNowMs() - start;
        AddFrameSectionTotal(name, ms);
        if (ms >= 1.0 && g_dualTickSectionCount < 32) g_dualTickSections[g_dualTickSectionCount++] = {name, ms};
    }
};

