// (v0.9.486) F9 during Lara's death. 0.9.485's log: an outfit switch asked during the F11 death waits for its object to
// load ("preload requested"), and when that took longer than the death's fade and reload delays the game's checkpoint
// reload came first. PSCAF_P_ProcessDeath (TR2 0x6FD7F0, retail 0x6727A0..; every frame of the death state) measures
// the time since the agent's +0x358 (the game clock in ms, retail 0x2D5796C, set by PSCAF_E_ProcessDeath) against the
// screen wipe's delay (+0x350, s) and the reload's (+0x354, s). The dying agent (and its Instance, +0x10, with its
// handle) is remembered here; while an outfit switch is in progress and that Instance is still the player's (same
// handle), +0x358 is set to the clock every tick: the fade and the reload wait, and the outfit's respawn comes first.
constexpr std::uintptr_t kRvaGameClockMs = 0x02D5796Cull;
constexpr std::ptrdiff_t kDeathStartMsOffset = 0x358, kAgentInstanceOffset = 0x10;
std::atomic<void*> g_deathAgent{nullptr};
void* g_deathAgentInstance = nullptr;
std::uint64_t g_deathAgentHandle = 0;

bool DeathAgentStillPlayerUnsafe() {
    void* player = CurrentPlayerInstance();
    return player && player == g_deathAgentInstance &&
           *reinterpret_cast<const std::uint64_t*>(static_cast<std::uint8_t*>(player) + kInstanceComponentIdOffset) == g_deathAgentHandle;
}

void ProcessDeathOutfitHoldGameThread() {
    static bool s_holding = false;
    void* agent = g_deathAgent.load(std::memory_order_acquire);
    if (!agent) return;
    bool same = false;
    __try {
        same = DeathAgentStillPlayerUnsafe();
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        same = false;
    }
    if (!same) {   // (respawned by the outfit switch, or reloaded by the game)
        g_deathAgent.store(nullptr, std::memory_order_release);
        if (s_holding) Log::Write("Player: the death's hold ended (Lara respawned)");
        s_holding = false;
        return;
    }
    if (!Features::OutfitSwapInProgress()) {
        if (s_holding) Log::Write("Player: the death's hold ended (no outfit switch in progress)");
        s_holding = false;
        return;
    }
    __try {
        *reinterpret_cast<std::uint32_t*>(static_cast<std::uint8_t*>(agent) + kDeathStartMsOffset) =
            *reinterpret_cast<const std::uint32_t*>(GameBuild::Base() + kRvaGameClockMs);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        g_deathAgent.store(nullptr, std::memory_order_release);
        return;
    }
    if (!s_holding) {
        s_holding = true;
        Log::Write("Player: an outfit switch during Lara's death: the death's fade and checkpoint reload wait for it");
    }
}

void __fastcall HookProcessDeath(void* agent) {
    
    
    const float requested = std::clamp(g_deathReloadDelay.load(std::memory_order_relaxed), 0.0f, 60.0f);
    if (agent && requested > 0.0f) {
        auto* bytes = reinterpret_cast<std::uint8_t*>(agent);
        float& screenwipe = *reinterpret_cast<float*>(bytes + kDeathScreenwipeSecondsOffset);
        float& reload = *reinterpret_cast<float*>(bytes + kDeathReloadSecondsOffset);

        if (!std::isfinite(screenwipe) || screenwipe < 0.0f)
            screenwipe = 0.0f;

        
        
        
        if (screenwipe >= requested) {
            const float desiredFade = std::min(0.25f, requested);
            screenwipe = std::max(0.0f, requested - desiredFade);
        }
        reload = requested;
        Log::Detailf("Player: death reload delay override %.3fs (screenwipe starts %.3fs)",
                    requested, screenwipe);
    }
    g_originalProcessDeath(agent);
    if (agent) {   // (v0.9.486) the dying agent, for an outfit switch during the death
        __try {
            void* instance = *reinterpret_cast<void* const*>(static_cast<std::uint8_t*>(agent) + kAgentInstanceOffset);
            if (instance && instance == CurrentPlayerInstance()) {
                g_deathAgentInstance = instance;
                g_deathAgentHandle =
                    *reinterpret_cast<const std::uint64_t*>(static_cast<std::uint8_t*>(instance) + kInstanceComponentIdOffset);
                g_deathAgent.store(agent, std::memory_order_release);
            }
        } __except (EXCEPTION_EXECUTE_HANDLER) {
        }
    }
    MenuGates gates;   // (v0.9.482) the map it blocks, watched until she is back in play
    if (ReadMenuGates(gates) && gates.status == 0) g_deathMapBlockAt.store(GetTickCount64(), std::memory_order_release);
}

