ULONGLONG WetVisualPrewarmScanIntervalMs(unsigned int pairCount) {
    const ULONGLONG totalItems = std::max<ULONGLONG>(1, static_cast<ULONGLONG>(pairCount) * 40ull);
    
    
    
    
    return std::max<ULONGLONG>(1, kWetVisualPrewarmScanBudgetMs / totalItems);
}


bool WetMaterialRenderStateMatches(const NativeMaterialData* dryData,
                                   const NativeMaterialData* wetData) {
    if (!dryData || !wetData) return false;
    return dryData->colorWriteMask == wetData->colorWriteMask &&
           dryData->blendMode == wetData->blendMode &&
           dryData->blendFactor == wetData->blendFactor &&
           dryData->fogType == wetData->fogType &&
           dryData->fadeMode == wetData->fadeMode &&
           dryData->flags == wetData->flags &&
           dryData->combinedNodeFlags == wetData->combinedNodeFlags &&
           dryData->alphaBloomBlendMode == wetData->alphaBloomBlendMode &&
           dryData->alphaTestRef == wetData->alphaTestRef &&
           dryData->depthWriteAlphaThreshold == wetData->depthWriteAlphaThreshold;
}

bool WetMaterialStageTexturesMatch(NativeMaterialTextureEntry* dryTextures, std::uint32_t dryCount,
                                   NativeMaterialTextureEntry* wetTextures, std::uint32_t wetCount) {
    if (dryCount != wetCount) return false;
    if (!dryCount) return true;
    if (!dryTextures || !wetTextures ||
        !IsReadableRange(dryTextures, static_cast<std::size_t>(dryCount) * sizeof(NativeMaterialTextureEntry)) ||
        !IsReadableRange(wetTextures, static_cast<std::size_t>(wetCount) * sizeof(NativeMaterialTextureEntry)))
        return false;
    for (std::uint32_t i = 0; i < dryCount; ++i) {
        if (dryTextures[i].texture != wetTextures[i].texture ||
            dryTextures[i].packed != wetTextures[i].packed ||
            std::fabs(dryTextures[i].mipLodBias - wetTextures[i].mipLodBias) > 1.0e-6f)
            return false;
    }
    return true;
}

bool WetMaterialPassShadersMatch(const NativeMaterialPassData* dryPass,
                                 const NativeMaterialPassData* wetPass) {
    if (!dryPass || !wetPass) return dryPass == wetPass;
    if (dryPass->pixelShader != wetPass->pixelShader ||
        dryPass->vertexShader != wetPass->vertexShader)
        return false;
    const auto* dryHd = dryPass->hullDomain;
    const auto* wetHd = wetPass->hullDomain;
    if (!dryHd || !wetHd) return dryHd == wetHd;
    if (!IsReadableRange(dryHd, sizeof(NativeMaterialHullDomainData)) ||
        !IsReadableRange(wetHd, sizeof(NativeMaterialHullDomainData)))
        return false;
    return dryHd->hullShader == wetHd->hullShader &&
           dryHd->domainShader == wetHd->domainShader;
}

void AddWetVisualConstantBlock(WetVisualState& state, void* wetMaterial,
                               int passIndex, int stage,
                               const float* dryConstants, const float* wetConstants,
                               std::uint32_t constantCount,
                               bool prepareFastUpload = true) {
    constantCount = std::min(constantCount, kMaterialMaxConstantsPerStage);
    if (!constantCount || !dryConstants || !wetConstants) return;
    const std::size_t scalarCount = static_cast<std::size_t>(constantCount) * 4u;
    if (!IsReadableRange(dryConstants, scalarCount * sizeof(float)) ||
        !IsReadableRange(wetConstants, scalarCount * sizeof(float)))
        return;

    bool differs = false;
    for (std::size_t i = 0; i < scalarCount; ++i) {
        const float a = dryConstants[i];
        const float b = wetConstants[i];
        if (!std::isfinite(a) || !std::isfinite(b)) return;
        if (std::fabs(a - b) > 1.0e-7f) differs = true;
    }
    if (!differs) return;

    const auto duplicate = std::find_if(state.blocks.begin(), state.blocks.end(),
        [=](const WetVisualConstantBlock& block) {
            return block.wetMaterial == wetMaterial && block.passIndex == passIndex && block.stage == stage;
        });
    if (duplicate != state.blocks.end()) return;

    if (state.blocks.size() >= kWetVisualMaxConstantBlocks) {
        ++state.stateMismatchCount;
        return;
    }

    WetVisualConstantBlock block{};
    block.wetMaterial = wetMaterial;
    block.passIndex = passIndex;
    block.stage = stage;
    block.constantCount = constantCount;
    block.scalarCount = scalarCount;
    block.values.resize(scalarCount * 4u);
    float* dryValues = block.values.data();
    float* wetValues = dryValues + scalarCount;
    float* deltaValues = wetValues + scalarCount;
    std::memcpy(dryValues, dryConstants, scalarCount * sizeof(float));
    std::memcpy(wetValues, wetConstants, scalarCount * sizeof(float));
    for (std::size_t i = 0; i < scalarCount; ++i)
        deltaValues[i] = wetValues[i] - dryValues[i];
    if (prepareFastUpload) {
        block.fastUploadAttempted = true;
        block.fastUploadReady = PrepareWetVisualFastUpload(block);
    }
    state.blocks.push_back(std::move(block));
}

bool BuildWetVisualState(void* component, unsigned int index,
                         const WetMaterialSwapTableRuntime& runtime,
                         WetVisualState& out) {
    std::array<WetMaterialSwapPairRuntime, kWetVisualMaxMaterialPairs> pairs{};
    unsigned int pairCount = 0;
    if (!TryReadWetMaterialSwapPairs(runtime.table, pairs.data(),
                                     static_cast<unsigned int>(pairs.size()), &pairCount))
        return false;

    WetVisualState built{};
    built.component = component;
    built.table = runtime.table;
    built.index = index;
    built.pairCount = pairCount;
    built.active = true;

    constexpr int stages[] = {
        Features::MaterialShaderStage_Pixel,
        Features::MaterialShaderStage_Vertex,
        Features::MaterialShaderStage_Hull,
        Features::MaterialShaderStage_Domain,
    };

    for (unsigned int pairIndex = 0; pairIndex < pairCount; ++pairIndex) {
        const std::uintptr_t dryAddress = NormalizeCommonMaterialAddress(pairs[pairIndex].originalInterface);
        const std::uintptr_t wetAddress = NormalizeCommonMaterialAddress(pairs[pairIndex].overrideInterface);
        if (!dryAddress || !wetAddress) {
            ++built.stateMismatchCount;
            continue;
        }
        void* dryMaterial = reinterpret_cast<void*>(dryAddress);
        void* wetMaterial = reinterpret_cast<void*>(wetAddress);
        const auto* dryData = SafeGetMaterialData(dryMaterial);
        const auto* wetData = SafeGetMaterialData(wetMaterial);
        if (!dryData || !wetData) {
            ++built.stateMismatchCount;
            continue;
        }
        if (!WetMaterialRenderStateMatches(dryData, wetData))
            ++built.stateMismatchCount;

        for (int passIndex = 0; passIndex < 10; ++passIndex) {
            const auto* dryPass = dryData->passData[passIndex];
            const auto* wetPass = wetData->passData[passIndex];
            if (!!dryPass != !!wetPass) {
                ++built.shaderMismatchCount;
                continue;
            }
            if (!dryPass) continue;
            if (!IsReadableRange(dryPass, sizeof(NativeMaterialPassData)) ||
                !IsReadableRange(wetPass, sizeof(NativeMaterialPassData))) {
                ++built.shaderMismatchCount;
                continue;
            }
            if (!WetMaterialPassShadersMatch(dryPass, wetPass)) {
                ++built.shaderMismatchCount;
                continue;
            }

            for (const int stage : stages) {
                NativeMaterialTextureEntry* dryTextures = nullptr;
                NativeMaterialTextureEntry* wetTextures = nullptr;
                std::uint32_t dryTextureCount = 0, wetTextureCount = 0;
                float* dryConstants = nullptr;
                float* wetConstants = nullptr;
                std::uint32_t dryConstantCount = 0, wetConstantCount = 0;
                const bool dryOk = ResolveMaterialStage(dryData, passIndex, stage,
                    dryTextures, dryTextureCount, dryConstants, dryConstantCount);
                const bool wetOk = ResolveMaterialStage(wetData, passIndex, stage,
                    wetTextures, wetTextureCount, wetConstants, wetConstantCount);
                if (dryOk != wetOk) {
                    ++built.shaderMismatchCount;
                    continue;
                }
                if (!dryOk) continue;
                if (!WetMaterialStageTexturesMatch(dryTextures, dryTextureCount,
                                                   wetTextures, wetTextureCount))
                    ++built.textureMismatchCount;
                if (dryConstantCount != wetConstantCount) {
                    ++built.stateMismatchCount;
                    continue;
                }
                AddWetVisualConstantBlock(built, wetMaterial, passIndex, stage,
                                          dryConstants, wetConstants, wetConstantCount);
            }
        }
    }

    out = std::move(built);
    return out.active;
}

bool HasReusableWetVisualSnapshot(void* component, unsigned int index, const void* table) {
    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    return g_wetVisualState.active &&
           g_wetVisualState.component == component &&
           g_wetVisualState.table == table &&
           g_wetVisualState.index == index;
}

bool QueueWetVisualPrewarm(void* component, unsigned int index,
                           const WetMaterialSwapTableRuntime& runtime, bool propagate) {
    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);

    if (g_wetVisualPrewarm.active) {
        if (g_wetVisualPrewarm.component == component &&
            g_wetVisualPrewarm.table == runtime.table &&
            g_wetVisualPrewarm.index == index) {
            g_wetVisualPrewarm.propagate = g_wetVisualPrewarm.propagate || propagate;
            return true;
        }
        
        g_wetVisualPrewarm = {};
    }

    WetVisualPrewarmState pending{};
    pending.active = true;
    pending.phase = WetVisualPrewarmPhase::Scanning;
    pending.component = component;
    pending.table = runtime.table;
    pending.index = index;
    pending.propagate = propagate;
    pending.runtime = runtime;
    pending.startedMs = GetTickCount64();
    pending.workStartMs = pending.startedMs;
    pending.nextWorkMs = pending.startedMs + kWetVisualPostWetKickoffDelayMs;

    pending.built.component = component;
    pending.built.table = runtime.table;
    pending.built.index = index;
    pending.built.active = true;
    
    
    pending.built.currentBlend = 1.0f;
    
    
    g_wetVisualPrewarm = std::move(pending);
    g_wetVisualPrewarmIndex.store(index, std::memory_order_relaxed);
    g_wetVisualPrewarmComponent.store(component, std::memory_order_release);
    g_wetVisualBlend.store(1.0f, std::memory_order_relaxed);
    g_wetVisualPhaseStatus.store(static_cast<int>(WetVisualPhase::Wet),
                                 std::memory_order_relaxed);
    g_wetVisualPrewarmPending.store(true, std::memory_order_release);
    return true;
}

bool CancelWetVisualPrewarm(void* component, unsigned int index, const void* table) {
    if (!g_wetVisualPrewarmPending.load(std::memory_order_acquire))
        return false;
    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    if (!g_wetVisualPrewarm.active ||
        g_wetVisualPrewarm.component != component ||
        g_wetVisualPrewarm.index != index ||
        g_wetVisualPrewarm.table != table)
        return false;
    g_wetVisualPrewarm = {};
    g_wetVisualPrewarmComponent.store(nullptr, std::memory_order_release);
    g_wetVisualPrewarmIndex.store(0xFFFFFFFFu, std::memory_order_relaxed);
    g_wetVisualPrewarmPending.store(false, std::memory_order_release);
    if (!g_wetVisualState.active) {
        g_wetVisualBlend.store(0.0f, std::memory_order_relaxed);
        g_wetVisualPhaseStatus.store(static_cast<int>(WetVisualPhase::Idle), std::memory_order_relaxed);
    }
    return true;
}

bool ProcessWetVisualPrewarmScanItemLocked() {
    auto& pending = g_wetVisualPrewarm;
    if (!pending.active || pending.phase != WetVisualPrewarmPhase::Scanning)
        return false;

    constexpr int stages[] = {
        Features::MaterialShaderStage_Pixel,
        Features::MaterialShaderStage_Vertex,
        Features::MaterialShaderStage_Hull,
        Features::MaterialShaderStage_Domain,
    };

    while (pending.pairIndex < pending.pairCount) {
        auto& cache = pending.pairCache[pending.pairIndex];
        if (!cache.initialized) {
            cache.initialized = true;
            const auto& pair = pending.pairs[pending.pairIndex];
            const std::uintptr_t dryAddress = NormalizeCommonMaterialAddress(pair.originalInterface);
            const std::uintptr_t wetAddress = NormalizeCommonMaterialAddress(pair.overrideInterface);
            if (!dryAddress || !wetAddress) {
                ++pending.built.stateMismatchCount;
                ++pending.pairIndex;
                pending.passIndex = 0;
                pending.stageIndex = 0;
                return true;
            }

            cache.dryMaterial = reinterpret_cast<void*>(dryAddress);
            cache.wetMaterial = reinterpret_cast<void*>(wetAddress);
            cache.dryData = SafeGetMaterialData(cache.dryMaterial);
            cache.wetData = SafeGetMaterialData(cache.wetMaterial);
            if (!cache.dryData || !cache.wetData) {
                ++pending.built.stateMismatchCount;
                ++pending.pairIndex;
                pending.passIndex = 0;
                pending.stageIndex = 0;
                return true;
            }
            cache.valid = true;
            if (!WetMaterialRenderStateMatches(cache.dryData, cache.wetData))
                ++pending.built.stateMismatchCount;
        }

        if (!cache.valid) {
            ++pending.pairIndex;
            pending.passIndex = 0;
            pending.stageIndex = 0;
            return true;
        }

        if (pending.passIndex >= 10) {
            ++pending.pairIndex;
            pending.passIndex = 0;
            pending.stageIndex = 0;
            pending.currentDryPass = nullptr;
            pending.currentWetPass = nullptr;
            return true;
        }

        const int passIndex = pending.passIndex;
        if (pending.stageIndex == 0) {
            pending.currentDryPass = cache.dryData->passData[passIndex];
            pending.currentWetPass = cache.wetData->passData[passIndex];
            if (!!pending.currentDryPass != !!pending.currentWetPass) {
                ++pending.built.shaderMismatchCount;
                ++pending.passIndex;
                return true;
            }
            if (!pending.currentDryPass) {
                ++pending.passIndex;
                return true;
            }
            if (!IsReadableRange(pending.currentDryPass, sizeof(NativeMaterialPassData)) ||
                !IsReadableRange(pending.currentWetPass, sizeof(NativeMaterialPassData))) {
                ++pending.built.shaderMismatchCount;
                ++pending.passIndex;
                return true;
            }
            if (!WetMaterialPassShadersMatch(pending.currentDryPass, pending.currentWetPass)) {
                ++pending.built.shaderMismatchCount;
                ++pending.passIndex;
                return true;
            }
        }

        const int stage = stages[pending.stageIndex];
        NativeMaterialTextureEntry* dryTextures = nullptr;
        NativeMaterialTextureEntry* wetTextures = nullptr;
        std::uint32_t dryTextureCount = 0, wetTextureCount = 0;
        float* dryConstants = nullptr;
        float* wetConstants = nullptr;
        std::uint32_t dryConstantCount = 0, wetConstantCount = 0;
        const bool dryOk = ResolveMaterialStage(cache.dryData, passIndex, stage,
            dryTextures, dryTextureCount, dryConstants, dryConstantCount);
        const bool wetOk = ResolveMaterialStage(cache.wetData, passIndex, stage,
            wetTextures, wetTextureCount, wetConstants, wetConstantCount);
        if (dryOk != wetOk) {
            ++pending.built.shaderMismatchCount;
        } else if (dryOk) {
            if (!WetMaterialStageTexturesMatch(dryTextures, dryTextureCount,
                                               wetTextures, wetTextureCount))
                ++pending.built.textureMismatchCount;
            if (dryConstantCount != wetConstantCount) {
                ++pending.built.stateMismatchCount;
            } else {
                
                
                
                AddWetVisualConstantBlock(pending.built, cache.wetMaterial, passIndex, stage,
                                          dryConstants, wetConstants, wetConstantCount, false);
            }
        }

        ++pending.stageIndex;
        if (pending.stageIndex >= 4) {
            pending.stageIndex = 0;
            ++pending.passIndex;
            pending.currentDryPass = nullptr;
            pending.currentWetPass = nullptr;
        }
        return true;
    }

    pending.phase = WetVisualPrewarmPhase::Priming;
    pending.primeIndex = 0;
    return false;
}

bool UploadWetVisualBlockForState(WetVisualState& state,
                                      WetVisualConstantBlock& block, float blend) {
    blend = std::clamp(blend, 0.0f, 1.0f);
    if (!block.scalarCount || block.values.size() != block.scalarCount * 4u)
        return false;

    float* dryValues = block.values.data();
    float* deltaValues = dryValues + block.scalarCount * 2u;
    float* scratch = dryValues + block.scalarCount * 3u;
    for (std::size_t i = 0; i < block.scalarCount; ++i)
        scratch[i] = dryValues[i] + deltaValues[i] * blend;

    bool uploaded = false;
    const double uploadStart = DualDiagNowMs();
    if (block.fastUploadReady)
        uploaded = FastUploadWetVisualConstantBuffer(block, scratch);

    if (!uploaded) {
        uploaded = SafeUploadMaterialConstantBuffer(block.wetMaterial, block.passIndex, block.stage,
                                                    scratch, block.constantCount);
        if (uploaded) {
            block.fastUploadAttempted = true;
            block.fastUploadReady = PrepareWetVisualFastUpload(block);
        }
    }
    const double uploadMs = DualDiagNowMs() - uploadStart;
    ++g_wetUploadCount;
    g_wetUploadTotalMs += uploadMs;
    g_wetUploadMaxMs = std::max(g_wetUploadMaxMs, uploadMs);

    if (uploaded) {
        block.lastUploadedBlend = blend;
        block.lastUploadMs = GetTickCount64();
        return true;
    }

    ++state.uploadFailureCount;
    return false;
}

bool UploadWetVisualBlockLocked(WetVisualConstantBlock& block, float blend) {
    return UploadWetVisualBlockForState(g_wetVisualState, block, blend);
}

void PublishWetVisualStateLocked();

void ServiceWetVisualPrewarmGameThread() {
    if (!g_wetVisualPrewarmPending.load(std::memory_order_acquire))
        return;


    {
        std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
        auto& pending = g_wetVisualPrewarm;
        if (!pending.active) {
            g_wetVisualPrewarmPending.store(false, std::memory_order_release);
            return;
        }

        const ULONGLONG now = GetTickCount64();
        
        
        
        if (now < pending.nextWorkMs)
            return;

        
        
        
        g_wetVisualPhaseStatus.store(static_cast<int>(WetVisualPhase::Wet),
                                     std::memory_order_relaxed);
        g_wetVisualBlend.store(1.0f, std::memory_order_relaxed);

        WetMaterialSwapTableRuntime current{};
        if (!ResolveWetMaterialSwapTable(pending.component, pending.index, &current) ||
            current.componentData != pending.runtime.componentData ||
            current.table != pending.table) {
            Log::Detail("Wet material transition: cancelled post-wet preparation because wet_hair lifetime changed");
            g_wetVisualPrewarm = {};
            g_wetVisualPrewarmComponent.store(nullptr, std::memory_order_release);
            g_wetVisualPrewarmIndex.store(0xFFFFFFFFu, std::memory_order_relaxed);
            g_wetVisualPrewarmPending.store(false, std::memory_order_release);
            if (!g_wetVisualState.active) {
                g_wetVisualBlend.store(0.0f, std::memory_order_relaxed);
                g_wetVisualPhaseStatus.store(static_cast<int>(WetVisualPhase::Idle),
                                             std::memory_order_relaxed);
            }
            return;
        }

        
        
        
        if (pending.pairCount == 0) {
            if (!TryReadWetMaterialSwapPairs(pending.table, pending.pairs.data(),
                                             static_cast<unsigned int>(pending.pairs.size()),
                                             &pending.pairCount)) {
                Log::Write("Wet material transition: post-wet pair discovery failed; keeping native wet_hair behavior");
                g_wetVisualPrewarm = {};
                g_wetVisualPrewarmComponent.store(nullptr, std::memory_order_release);
                g_wetVisualPrewarmIndex.store(0xFFFFFFFFu, std::memory_order_relaxed);
                g_wetVisualPrewarmPending.store(false, std::memory_order_release);
                return;
            }
            pending.built.pairCount = pending.pairCount;
            pending.nextWorkMs = now + WetVisualPrewarmScanIntervalMs(pending.pairCount);
            return;
        }

        if (pending.phase == WetVisualPrewarmPhase::Scanning) {
            ProcessWetVisualPrewarmScanItemLocked();
            if (pending.phase == WetVisualPrewarmPhase::Priming) {
                const ULONGLONG targetEnd = pending.startedMs + kWetVisualPrewarmTargetMs;
                const ULONGLONG remainingMs = targetEnd > now ? targetEnd - now : 1;
                const std::size_t bindOps = std::max<std::size_t>(1, pending.built.blocks.size());
                pending.nextWorkMs = now +
                    std::max<ULONGLONG>(1, remainingMs / static_cast<ULONGLONG>(bindOps));
            } else {
                pending.nextWorkMs = now + WetVisualPrewarmScanIntervalMs(pending.pairCount);
            }
            return;
        }

        if (pending.phase == WetVisualPrewarmPhase::Priming) {
            
            
            
            
            if (pending.primeIndex < pending.built.blocks.size()) {
                auto& block = pending.built.blocks[pending.primeIndex];
                if (!block.fastUploadAttempted) {
                    block.fastUploadAttempted = true;
                    block.fastUploadReady = PrepareWetVisualFastUpload(block);
                }
                ++pending.primeIndex;

                const ULONGLONG targetEnd = pending.startedMs + kWetVisualPrewarmTargetMs;
                const ULONGLONG remainingMs = targetEnd > now ? targetEnd - now : 1;
                const std::size_t blocksLeft = pending.built.blocks.size() - pending.primeIndex;
                const std::size_t remainingOps = std::max<std::size_t>(1, blocksLeft);
                pending.nextWorkMs = now +
                    std::max<ULONGLONG>(1, remainingMs / static_cast<ULONGLONG>(remainingOps));
                if (pending.primeIndex < pending.built.blocks.size())
                    return;
            }

            {
                const unsigned fastCount = static_cast<unsigned>(std::count_if(
                    pending.built.blocks.begin(), pending.built.blocks.end(),
                    [](const WetVisualConstantBlock& b) { return b.fastUploadReady; }));
                Log::Detailf(
                    "Wet material transition: snapshot prepared after the first wet Swap in %llu ms: pairs=%u "
                    "changedCBs=%u fastCBs=%u shaderMismatch=%u textureMismatch=%u stateMismatch=%u",
                    static_cast<unsigned long long>(now - pending.startedMs), pending.built.pairCount,
                    static_cast<unsigned>(pending.built.blocks.size()), fastCount,
                    pending.built.shaderMismatchCount, pending.built.textureMismatchCount,
                    pending.built.stateMismatchCount);
            }
            g_wetVisualState = std::move(pending.built);
            g_wetVisualState.currentBlend = 1.0f;
            g_wetVisualState.nextUploadBlock = 0;
            g_wetVisualState.phase = WetVisualPhase::Wet;
            g_wetVisualState.phaseStartMs = now;
            g_wetVisualState.phaseStartBlend = 1.0f;
            g_wetVisualState.phaseTargetBlend = 1.0f;
            g_wetVisualState.phaseDurationMs = 0.0f;
            PublishWetVisualStateLocked();

            g_wetVisualPrewarm = {};
            g_wetVisualPrewarmComponent.store(nullptr, std::memory_order_release);
            g_wetVisualPrewarmIndex.store(0xFFFFFFFFu, std::memory_order_relaxed);
            g_wetVisualPrewarmPending.store(false, std::memory_order_release);
        }
    }
}

void FlushWetVisualPrewarmToNativeGameThread() {
    if (!g_wetVisualPrewarmPending.load(std::memory_order_acquire))
        return;

    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    g_wetVisualPrewarm = {};
    g_wetVisualPrewarmComponent.store(nullptr, std::memory_order_release);
    g_wetVisualPrewarmIndex.store(0xFFFFFFFFu, std::memory_order_relaxed);
    g_wetVisualPrewarmPending.store(false, std::memory_order_release);
    
    
    
}

bool ApplyWetVisualBlendLocked(float blend) {
    if (!g_wetVisualState.active) return false;
    blend = std::clamp(blend, 0.0f, 1.0f);
    bool any = false;
    for (auto& block : g_wetVisualState.blocks)
        any |= UploadWetVisualBlockLocked(block, blend);
    g_wetVisualState.currentBlend = blend;
    g_wetVisualState.lastUploadMs = GetTickCount64();
    g_wetVisualBlend.store(blend, std::memory_order_relaxed);
    g_wetVisualUploadFailures.store(g_wetVisualState.uploadFailureCount, std::memory_order_relaxed);
    return any;
}

float CurrentWetVisualBlendLocked(ULONGLONG now) {
    if (!g_wetVisualState.active) return 0.0f;
    if (g_wetVisualState.phase != WetVisualPhase::Wetting &&
        g_wetVisualState.phase != WetVisualPhase::Drying)
        return g_wetVisualState.currentBlend;
    if (g_wetVisualState.phaseDurationMs <= 0.0f)
        return g_wetVisualState.phaseTargetBlend;
    const float elapsed = static_cast<float>(now - g_wetVisualState.phaseStartMs);
    const float t = std::clamp(elapsed / g_wetVisualState.phaseDurationMs, 0.0f, 1.0f);
    return g_wetVisualState.phaseStartBlend +
        (g_wetVisualState.phaseTargetBlend - g_wetVisualState.phaseStartBlend) * t;
}

void PublishWetVisualStateLocked() {
    g_wetVisualBlockCount.store(static_cast<int>(g_wetVisualState.blocks.size()), std::memory_order_relaxed);
    g_wetVisualShaderMismatches.store(g_wetVisualState.shaderMismatchCount, std::memory_order_relaxed);
    g_wetVisualTextureMismatches.store(g_wetVisualState.textureMismatchCount, std::memory_order_relaxed);
    g_wetVisualStateMismatches.store(g_wetVisualState.stateMismatchCount, std::memory_order_relaxed);
    g_wetVisualUploadFailures.store(g_wetVisualState.uploadFailureCount, std::memory_order_relaxed);
    g_wetVisualPhaseStatus.store(static_cast<int>(g_wetVisualState.phase), std::memory_order_relaxed);
    g_wetVisualBlend.store(g_wetVisualState.currentBlend, std::memory_order_relaxed);
    g_wetVisualKnownIndex.store(g_wetVisualState.index, std::memory_order_relaxed);
    g_wetVisualKnownComponent.store(g_wetVisualState.component, std::memory_order_release);
}

// The uploads of one wet-in / dry-out (under g_wetMaterialMutex; a few logged a session).
void MarkWetVisualPhaseStartLocked() {
    g_wetPhaseUploadsAtStart = g_wetUploadCount;
    g_wetPhaseUploadMsAtStart = g_wetUploadTotalMs;
}
void LogWetVisualPhaseEndLocked(const char* phase) {
    if (g_wetPhaseLogs >= 8) return;
    ++g_wetPhaseLogs;
    Log::Detailf("Wet material transition: %s done: %u constant upload(s) in %.2f ms (slowest upload so far %.2f ms, "
                "%u blocks)",
                phase, g_wetUploadCount - g_wetPhaseUploadsAtStart, g_wetUploadTotalMs - g_wetPhaseUploadMsAtStart,
                g_wetUploadMaxMs, static_cast<unsigned>(g_wetVisualState.blocks.size()));
}

bool BeginWetVisualWetting(void* component, unsigned int index,
                           const WetMaterialSwapTableRuntime& runtime) {
    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    MarkWetVisualPhaseStartLocked();
    const ULONGLONG now = GetTickCount64();
    const bool same = g_wetVisualState.active && g_wetVisualState.component == component &&
                      g_wetVisualState.table == runtime.table && g_wetVisualState.index == index;

    if (same) {
        
        
        
        
        
        if (g_wetVisualState.phase == WetVisualPhase::Wet ||
            g_wetVisualState.phase == WetVisualPhase::Wetting) {
            return !g_wetVisualState.blocks.empty();
        }

        if (g_wetVisualState.phase == WetVisualPhase::Drying) {
            
            
            
            const float current = CurrentWetVisualBlendLocked(now);
            const float wetSeconds = std::clamp(
                g_wetMaterialWetInSeconds.load(std::memory_order_relaxed), 0.05f, 30.0f);
            g_wetVisualState.currentBlend = current;
            g_wetVisualState.phase = WetVisualPhase::Wetting;
            g_wetVisualState.phaseStartMs = now;
            g_wetVisualState.phaseStartBlend = current;
            g_wetVisualState.phaseTargetBlend = 1.0f;
            g_wetVisualState.phaseDurationMs = wetSeconds * 1000.0f * std::max(0.0f, 1.0f - current);
            PublishWetVisualStateLocked();
            return !g_wetVisualState.blocks.empty();
        }

        
        
        
        
        
        
        
        bool allBlocksDry = true;
        for (const auto& block : g_wetVisualState.blocks) {
            if (std::fabs(block.lastUploadedBlend) > 1.0e-5f) {
                allBlocksDry = false;
                break;
            }
        }
        if (!allBlocksDry)
            ApplyWetVisualBlendLocked(0.0f);
        else
            g_wetVisualState.currentBlend = 0.0f;
        g_wetVisualHiddenDryCleanupPending.store(false, std::memory_order_release);
    } else {
        WetVisualState replacement{};
        if (!BuildWetVisualState(component, index, runtime, replacement))
            return false;
        g_wetVisualState = std::move(replacement);
        g_wetVisualState.currentBlend = 0.0f;
        
        
        
        ApplyWetVisualBlendLocked(0.0f);
        const unsigned int fastCbCount = static_cast<unsigned int>(std::count_if(
            g_wetVisualState.blocks.begin(), g_wetVisualState.blocks.end(),
            [](const WetVisualConstantBlock& block) { return block.fastUploadReady; }));
        Log::Detailf(
            "Wet material transition: visual snapshot pairs=%u changedCBs=%u fastCBs=%u shaderMismatch=%u textureMismatch=%u stateMismatch=%u",
            g_wetVisualState.pairCount, static_cast<unsigned int>(g_wetVisualState.blocks.size()),
            fastCbCount, g_wetVisualState.shaderMismatchCount, g_wetVisualState.textureMismatchCount,
            g_wetVisualState.stateMismatchCount);
    }

    const float wetSeconds = std::clamp(
        g_wetMaterialWetInSeconds.load(std::memory_order_relaxed), 0.05f, 30.0f);
    const float start = g_wetVisualState.currentBlend;
    g_wetVisualState.phase = WetVisualPhase::Wetting;
    g_wetVisualState.phaseStartMs = now;
    g_wetVisualState.phaseStartBlend = start;
    g_wetVisualState.phaseTargetBlend = 1.0f;
    g_wetVisualState.phaseDurationMs = wetSeconds * 1000.0f * std::max(0.0f, 1.0f - start);
    PublishWetVisualStateLocked();
    return !g_wetVisualState.blocks.empty();
}

void BeginWetVisualDrying(void* component, unsigned int index,
                          const WetMaterialSwapTableRuntime& runtime) {
    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    if (!g_wetVisualState.active || g_wetVisualState.component != component ||
        g_wetVisualState.table != runtime.table || g_wetVisualState.index != index)
        return;
    
    
    if (g_wetVisualState.phase == WetVisualPhase::Drying)
        return;
    const ULONGLONG now = GetTickCount64();
    const float current = CurrentWetVisualBlendLocked(now);
    const float drySeconds = std::clamp(
        g_wetMaterialDryOutSeconds.load(std::memory_order_relaxed), 0.25f, 300.0f);
    MarkWetVisualPhaseStartLocked();
    g_wetVisualState.currentBlend = current;
    g_wetVisualState.phase = WetVisualPhase::Drying;
    g_wetVisualState.phaseStartMs = now;
    g_wetVisualState.phaseStartBlend = current;
    g_wetVisualState.phaseTargetBlend = 0.0f;
    g_wetVisualState.phaseDurationMs = drySeconds * 1000.0f * std::max(0.0f, current);
    PublishWetVisualStateLocked();
}

void UpdateWetVisualTransitionGameThread() {
    const int publishedPhase = g_wetVisualPhaseStatus.load(std::memory_order_relaxed);
    if (publishedPhase != static_cast<int>(WetVisualPhase::Wetting) &&
        publishedPhase != static_cast<int>(WetVisualPhase::Drying))
        return;

    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    if (!g_wetVisualState.active) return;
    if (g_wetVisualState.phase != WetVisualPhase::Wetting &&
        g_wetVisualState.phase != WetVisualPhase::Drying)
        return;

    const ULONGLONG now = GetTickCount64();
    const ULONGLONG durationMs = static_cast<ULONGLONG>(
        std::max(0.0f, g_wetVisualState.phaseDurationMs));
    const bool reachingTarget = now - g_wetVisualState.phaseStartMs >= durationMs;
    const float blend = reachingTarget
        ? g_wetVisualState.phaseTargetBlend
        : CurrentWetVisualBlendLocked(now);

    
    
    
    g_wetVisualState.currentBlend = blend;
    g_wetVisualBlend.store(blend, std::memory_order_relaxed);

    if (g_wetVisualState.blocks.empty()) {
        if (reachingTarget && g_wetVisualState.phaseTargetBlend >= 0.999f) {
            g_wetVisualState.phase = WetVisualPhase::Wet;
            PublishWetVisualStateLocked();
        }
        return;
    }

    
    
    
    const std::size_t blockCount = g_wetVisualState.blocks.size();
    bool uploadedOne = false;
    bool allAtTarget = true;
    // Steps: about kWetVisualWetInSteps / kWetVisualDryOutSteps uploads a block over the phase (each upload makes the
    // game create an upload resource), never one of the value already uploaded.
    const bool wetting = g_wetVisualState.phase == WetVisualPhase::Wetting;
    const float steps = wetting ? kWetVisualWetInSteps : kWetVisualDryOutSteps;
    const ULONGLONG stepIntervalMs = std::clamp<ULONGLONG>(
        static_cast<ULONGLONG>(static_cast<float>(durationMs) / steps),
        kWetVisualMinUploadIntervalMs, kWetVisualMaxStepIntervalMs);
    const float stepBlend = std::max(kWetVisualMinBlendStep,
        std::fabs(g_wetVisualState.phaseTargetBlend - g_wetVisualState.phaseStartBlend) / steps);
    const ULONGLONG catchUpMs = std::max<ULONGLONG>(kWetVisualMaxUploadIntervalMs, stepIntervalMs * 2);
    for (std::size_t scan = 0; scan < blockCount; ++scan) {
        const std::size_t idx = (g_wetVisualState.nextUploadBlock + scan) % blockCount;
        auto& block = g_wetVisualState.blocks[idx];
        const float delta = std::fabs(blend - block.lastUploadedBlend);
        if (delta > 1.0e-5f) allAtTarget = false;
        if (uploadedOne || delta <= 1.0e-5f) continue;

        const ULONGLONG sinceUpload = now - block.lastUploadMs;
        const bool endpointNeeded = reachingTarget;
        const bool cadenceNeeded = sinceUpload >= stepIntervalMs &&
            (delta >= stepBlend - 1.0e-6f || sinceUpload >= catchUpMs);
        if (!endpointNeeded && !cadenceNeeded) continue;

        if (UploadWetVisualBlockLocked(block, blend)) {
            uploadedOne = true;
            g_wetVisualState.nextUploadBlock = (idx + 1) % blockCount;
            g_wetVisualState.lastUploadMs = now;
        }
    }

    
    
    
    
    if (reachingTarget && g_wetVisualState.phaseTargetBlend >= 0.999f) {
        allAtTarget = true;
        for (const auto& block : g_wetVisualState.blocks) {
            if (std::fabs(1.0f - block.lastUploadedBlend) > 1.0e-5f) {
                allAtTarget = false;
                break;
            }
        }
        if (allAtTarget) {
            g_wetVisualState.phase = WetVisualPhase::Wet;
            PublishWetVisualStateLocked();
            LogWetVisualPhaseEndLocked("wet-in");
        }
    }
}

void ServiceWetVisualHiddenDryCleanupGameThread() {
    if (!g_wetVisualHiddenDryCleanupPending.load(std::memory_order_acquire))
        return;

    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    if (!g_wetVisualState.active || g_wetVisualState.phase != WetVisualPhase::Idle) {
        g_wetVisualHiddenDryCleanupPending.store(false, std::memory_order_release);
        return;
    }

    
    
    
    
    for (auto& block : g_wetVisualState.blocks) {
        if (std::fabs(block.lastUploadedBlend) <= 1.0e-5f) continue;
        UploadWetVisualBlockLocked(block, 0.0f);
        return;
    }

    g_wetVisualHiddenDryCleanupPending.store(false, std::memory_order_release);
}

void AbortWetVisualTransition() {
    g_wetVisualHiddenDryCleanupPending.store(false, std::memory_order_release);
    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    if (!g_wetVisualState.active) return;
    
    
    
    ApplyWetVisualBlendLocked(1.0f);
    g_wetVisualState = {};
    g_wetVisualBlend.store(0.0f, std::memory_order_relaxed);
    g_wetVisualBlockCount.store(0, std::memory_order_relaxed);
    g_wetVisualShaderMismatches.store(0, std::memory_order_relaxed);
    g_wetVisualTextureMismatches.store(0, std::memory_order_relaxed);
    g_wetVisualStateMismatches.store(0, std::memory_order_relaxed);
    g_wetVisualUploadFailures.store(0, std::memory_order_relaxed);
    g_wetVisualPhaseStatus.store(static_cast<int>(WetVisualPhase::Idle), std::memory_order_relaxed);
    g_wetVisualKnownComponent.store(nullptr, std::memory_order_release);
    g_wetVisualKnownIndex.store(0xFFFFFFFFu, std::memory_order_relaxed);
}

void FinishWetVisualRestore(void* component, unsigned int index, const void* table) {
    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    if (!g_wetVisualState.active || g_wetVisualState.component != component ||
        g_wetVisualState.table != table || g_wetVisualState.index != index)
        return;

    
    
    
    
    
    
    if (g_wetVisualState.phase == WetVisualPhase::Drying) LogWetVisualPhaseEndLocked("dry-out");
    g_wetVisualState.phase = WetVisualPhase::Idle;
    g_wetVisualState.phaseStartMs = 0;
    g_wetVisualState.phaseStartBlend = 0.0f;
    g_wetVisualState.phaseTargetBlend = 0.0f;
    g_wetVisualState.phaseDurationMs = 0.0f;
    g_wetVisualState.currentBlend = 0.0f;
    g_wetVisualBlend.store(0.0f, std::memory_order_relaxed);
    bool needsHiddenCleanup = false;
    for (const auto& block : g_wetVisualState.blocks) {
        if (std::fabs(block.lastUploadedBlend) > 1.0e-5f) {
            needsHiddenCleanup = true;
            break;
        }
    }
    g_wetVisualHiddenDryCleanupPending.store(needsHiddenCleanup, std::memory_order_release);
    PublishWetVisualStateLocked();
}

bool PlayerPropWetTuningPlausible(void* playerProp) {
    return TryReadWetPlayerPropTuning(playerProp);
}

void ResetWetPlayerPropDiscovery() {
    g_wetMaterialPlayerProp.store(nullptr, std::memory_order_release);
    g_wetMaterialResolvedPlayer.store(nullptr, std::memory_order_relaxed);
    g_wetMaterialResolvedInstance.store(nullptr, std::memory_order_relaxed);
    g_wetMaterialResolvedComponent.store(nullptr, std::memory_order_relaxed);
    g_wetMaterialNativeTuningReady.store(false, std::memory_order_release);
    g_wetMaterialNextDiscoveryMs.store(0, std::memory_order_relaxed);
}

bool TryReadInstanceComponentArray(void* instance, int& countOut, void*** componentsOut) {
    if (!instance || !componentsOut) return false;
    __try {
        auto* bytes = reinterpret_cast<std::uint8_t*>(instance);
        const int count = *reinterpret_cast<const int*>(bytes + kInstanceComponentCountOffset);
        void** components = *reinterpret_cast<void***>(bytes + kInstanceComponentsOffset);
        if (!components || count <= 0 || count > 512) return false;
        
        
        volatile void* tail = components[count - 1];
        (void)tail;
        countOut = count;
        *componentsOut = components;
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

void* TryResolvePlayerPropFromComponent(void* component, void* instance, void* player,
                                        std::ptrdiff_t* playerOffsetOut = nullptr) {
    if (!component || !instance || !player) return nullptr;
    __try {
        auto* bytes = reinterpret_cast<std::uint8_t*>(component);
        if (*reinterpret_cast<void**>(bytes + kPlayerComponentOwnerInstanceOffset) != instance)
            return nullptr;

        
        
        if (*reinterpret_cast<void**>(bytes + kPlayerComponentPlayerOffset) == player) {
            void* prop = *reinterpret_cast<void**>(bytes + kPlayerComponentPlayerPropOffset);
            if (TryReadWetPlayerPropTuning(prop)) {
                if (playerOffsetOut) *playerOffsetOut = kPlayerComponentPlayerOffset;
                return prop;
            }
        }

        
        
        
        
        
        constexpr std::ptrdiff_t kSearchBegin = 0x80;
        constexpr std::ptrdiff_t kSearchEnd = 0x500;
        for (std::ptrdiff_t off = kSearchBegin; off + 0x10 <= kSearchEnd; off += sizeof(void*)) {
            if (*reinterpret_cast<void**>(bytes + off) != player) continue;
            void* prop = *reinterpret_cast<void**>(bytes + off + sizeof(void*));
            if (!TryReadWetPlayerPropTuning(prop)) continue;
            if (playerOffsetOut) *playerOffsetOut = off;
            return prop;
        }
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return nullptr;
    }
    return nullptr;
}

void* ResolveCurrentWetPlayerPropGameThread() {
    void* player = CurrentPlayer();
    void* instance = CurrentPlayerInstance();
    g_wetMaterialLocalInstance.store(instance, std::memory_order_release);
    if (!player || !instance) {
        if (g_wetMaterialResolvedInstance.load(std::memory_order_relaxed) != instance)
            ResetWetPlayerPropDiscovery();
        return nullptr;
    }

    void* cachedPlayer = g_wetMaterialResolvedPlayer.load(std::memory_order_relaxed);
    void* cachedInstance = g_wetMaterialResolvedInstance.load(std::memory_order_relaxed);
    void* cachedProp = g_wetMaterialPlayerProp.load(std::memory_order_acquire);
    if (cachedPlayer == player && cachedInstance == instance && cachedProp &&
        TryReadWetPlayerPropTuning(cachedProp)) {
        return cachedProp;
    }
    if (cachedProp) {
        g_wetMaterialPlayerProp.store(nullptr, std::memory_order_release);
        g_wetMaterialResolvedComponent.store(nullptr, std::memory_order_relaxed);
        g_wetMaterialNativeTuningReady.store(false, std::memory_order_release);
    }

    
    
    if ((cachedPlayer && cachedPlayer != player) || (cachedInstance && cachedInstance != instance)) {
        g_wetMaterialPlayerProp.store(nullptr, std::memory_order_release);
        g_wetMaterialResolvedPlayer.store(nullptr, std::memory_order_relaxed);
        g_wetMaterialResolvedInstance.store(nullptr, std::memory_order_relaxed);
        g_wetMaterialResolvedComponent.store(nullptr, std::memory_order_relaxed);
        g_wetMaterialNativeTuningReady.store(false, std::memory_order_release);
        g_wetMaterialNextDiscoveryMs.store(0, std::memory_order_relaxed);
    }

    
    
    
    
    const ULONGLONG now = GetTickCount64();
    if (now < g_wetMaterialNextDiscoveryMs.load(std::memory_order_relaxed)) return nullptr;
    g_wetMaterialNextDiscoveryMs.store(now + 1000, std::memory_order_relaxed);
    const auto attempt = g_wetDiscoveryAttempts.fetch_add(1, std::memory_order_relaxed) + 1;

    int count = 0;
    void** components = nullptr;
    if (!TryReadInstanceComponentArray(instance, count, &components)) return nullptr;

    for (int i = 0; i < count; ++i) {
        void* component = nullptr;
        __try { component = components[i]; }
        __except (EXCEPTION_EXECUTE_HANDLER) { component = nullptr; }
        if (!component) continue;

        std::ptrdiff_t playerOffset = 0;
        void* playerProp = TryResolvePlayerPropFromComponent(component, instance, player, &playerOffset);
        if (!playerProp) continue;

        g_wetMaterialResolvedPlayer.store(player, std::memory_order_relaxed);
        g_wetMaterialResolvedInstance.store(instance, std::memory_order_relaxed);
        g_wetMaterialResolvedComponent.store(component, std::memory_order_relaxed);
        g_wetMaterialPlayerProp.store(playerProp, std::memory_order_release);
        g_wetMaterialNextDiscoveryMs.store(0, std::memory_order_relaxed);
        g_wetMaterialTuningDirty.store(true, std::memory_order_release);

        float maxWet = 0.0f, drySpeed = 0.0f, wetSpeed = 0.0f;
        TryReadWetPlayerPropTuning(playerProp, &maxWet, &drySpeed, &wetSpeed);
        Log::Detailf(
            "Wet material transition: discovered retail Lara PlayerComponent=%p PlayerProp=%p "
            "playerOffset=0x%llX (attempt=%llu MaxWet=%.6g DryOffSpeed=%.6g WetSpeed=%.6g)",
            component, playerProp, static_cast<unsigned long long>(playerOffset),
            static_cast<unsigned long long>(attempt), maxWet, drySpeed, wetSpeed);
        return playerProp;
    }

    if (attempt == 1 || (attempt % 10) == 0) {
        Log::Detailf("Wet material transition: Lara PlayerProp discovery attempt %llu found no match; retrying at 1 Hz (components=%d)",
                    static_cast<unsigned long long>(attempt), count);
    }
    return nullptr;
}

void CancelPendingWetRestore(void* component, unsigned int index) {
    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    for (auto& pending : g_pendingWetMaterialRestores) {
        if (pending.active && pending.component == component && pending.index == index)
            pending = {};
    }
}

// A wet Swap starts the probe: its cost now, the game ticks of the next kWetSwapProbeWindowMs later.
void StartWetSwapProbe(double hookStartMs, double swapMs, bool firstPath) {
    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    if (g_wetSwapProbe.active || g_wetSwapProbesLogged >= kWetSwapProbeMaxLogs) return;
    const double now = DualDiagNowMs();
    g_wetSwapProbe = {};
    g_wetSwapProbe.active = true;
    g_wetSwapProbe.firstPath = firstPath;
    g_wetSwapProbe.startMs = now;
    g_wetSwapProbe.lastTickMs = now;
    g_wetSwapProbe.swapMs = swapMs;
    g_wetSwapProbe.hookMs = now - hookStartMs;
    g_wetSwapProbe.uploadsAtStart = g_wetUploadCount;
    g_wetSwapProbe.uploadMsAtStart = g_wetUploadTotalMs;
}

// Each game tick (before the wet material work): the gap since the last one, and the window's end.
void ServiceWetSwapProbeGameThread(double tickStartMs) {
    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    auto& probe = g_wetSwapProbe;
    if (!probe.active) return;
    const double gap = tickStartMs - probe.lastTickMs;
    if (gap > probe.longestGapMs) {
        probe.longestGapMs = gap;
        probe.longestGapAtMs = tickStartMs - probe.startMs;
    }
    probe.lastTickMs = tickStartMs;
    if (tickStartMs - probe.startMs < kWetSwapProbeWindowMs) return;
    ++g_wetSwapProbesLogged;
    Log::Detailf(
        "Wet material transition: wet Swap (%s): the game's Swap %.2f ms, the hook %.2f ms; next %.0f ms: longest "
        "frame gap %.1f ms at +%.0f ms, framework wet work max %.2f ms a tick, %u constant upload(s) in %.2f ms "
        "(slowest upload so far %.2f ms)",
        probe.firstPath ? "first: snapshot prepared after it" : "snapshot reused: smooth wet-in",
        probe.swapMs, probe.hookMs, kWetSwapProbeWindowMs, probe.longestGapMs, probe.longestGapAtMs,
        probe.longestWetTickMs, g_wetUploadCount - probe.uploadsAtStart, g_wetUploadTotalMs - probe.uploadMsAtStart,
        g_wetUploadMaxMs);
    probe.active = false;
}

void NoteWetTickCostGameThread(double ms) {
    std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
    if (g_wetSwapProbe.active) g_wetSwapProbe.longestWetTickMs = std::max(g_wetSwapProbe.longestWetTickMs, ms);
}

void __fastcall HookMaterialSwapSwap(void* self, unsigned int index, bool propagate) {
    const double hookStartMs = DualDiagNowMs();
    const bool enabled = g_wetMaterialTransitionEnabled.load(std::memory_order_relaxed);
    if (enabled) {
        
        
        
        if (g_wetVisualPrewarmPending.load(std::memory_order_acquire) &&
            self == g_wetVisualPrewarmComponent.load(std::memory_order_acquire) &&
            index == g_wetVisualPrewarmIndex.load(std::memory_order_relaxed)) {
            return;
        }

        
        
        
        const int phase = g_wetVisualPhaseStatus.load(std::memory_order_relaxed);
        if (self == g_wetVisualKnownComponent.load(std::memory_order_acquire) &&
            index == g_wetVisualKnownIndex.load(std::memory_order_relaxed) &&
            (phase == static_cast<int>(WetVisualPhase::Wet) ||
             phase == static_cast<int>(WetVisualPhase::Wetting))) {
            if (g_originalMaterialSwapSwap)
                g_originalMaterialSwapSwap(self, index, propagate);
            return;
        }

        g_wetRawSwapCalls.fetch_add(1, std::memory_order_relaxed);
        WetMaterialSwapTableRuntime runtime{};
        char debugName[96]{};
        const bool tableOk = ResolveMaterialSwapTable(self, index, &runtime, debugName, sizeof(debugName));

        if (tableOk && IsWetMaterialSwapName(debugName)) {
            
            
            
            CancelPendingWetRestore(self, index);

            bool visualPrepared = false;
            if (HasReusableWetVisualSnapshot(self, index, runtime.table)) {
                visualPrepared = BeginWetVisualWetting(self, index, runtime);
            } else {
                
                
                
                
                
                const double swapStartMs = DualDiagNowMs();
                if (g_originalMaterialSwapSwap)
                    g_originalMaterialSwapSwap(self, index, propagate);
                const double swapMs = DualDiagNowMs() - swapStartMs;
                const bool queuedPostWetPreparation =
                    QueueWetVisualPrewarm(self, index, runtime, propagate);

                g_wetSwapEvents.fetch_add(1, std::memory_order_relaxed);
                (void)queuedPostWetPreparation;
                StartWetSwapProbe(hookStartMs, swapMs, true);
                return;
            }

            g_wetSwapEvents.fetch_add(1, std::memory_order_relaxed);
            (void)visualPrepared;
            const double swapStartMs = DualDiagNowMs();
            if (g_originalMaterialSwapSwap)
                g_originalMaterialSwapSwap(self, index, propagate);
            StartWetSwapProbe(hookStartMs, DualDiagNowMs() - swapStartMs, false);
            return;
        }
    }
    if (g_originalMaterialSwapSwap)
        g_originalMaterialSwapSwap(self, index, propagate);
}

void __fastcall HookMaterialSwapRestore(void* self, unsigned int index) {
    if (!g_originalMaterialSwapRestore) return;
    if (!g_wetMaterialTransitionEnabled.load(std::memory_order_relaxed)) {
        g_originalMaterialSwapRestore(self, index);
        return;
    }

    g_wetRawRestoreCalls.fetch_add(1, std::memory_order_relaxed);
    WetMaterialSwapTableRuntime runtime{};
    char debugName[96]{};
    const bool tableOk = ResolveMaterialSwapTable(self, index, &runtime, debugName, sizeof(debugName));

    if (!tableOk || !IsWetMaterialSwapName(debugName)) {
        g_originalMaterialSwapRestore(self, index);
        return;
    }

    
    
    
    if (CancelWetVisualPrewarm(self, index, runtime.table)) {
        g_originalMaterialSwapRestore(self, index);
        return;
    }

    
    
    if (!HasReusableWetVisualSnapshot(self, index, runtime.table)) {
        g_originalMaterialSwapRestore(self, index);
        return;
    }

    const float drySeconds = std::clamp(
        g_wetMaterialDryOutSeconds.load(std::memory_order_relaxed), 0.25f, 300.0f);
    BeginWetVisualDrying(self, index, runtime);
    const ULONGLONG due = GetTickCount64() +
        static_cast<ULONGLONG>(std::llround(static_cast<double>(drySeconds) * 1000.0));

    bool queued = false;
    {
        std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
        for (const auto& pending : g_pendingWetMaterialRestores) {
            if (pending.active && pending.component == self && pending.index == index)
                return;
        }
        for (auto& pending : g_pendingWetMaterialRestores) {
            if (pending.active) continue;
            pending.component = self;
            pending.componentData = runtime.componentData;
            pending.table = runtime.table;
            pending.index = index;
            pending.dueMs = due;
            pending.active = true;
            queued = true;
            break;
        }
    }

    if (!queued) {
        Log::Detail("Wet material transition: deferred Restore queue full; using native immediate Restore");
        g_originalMaterialSwapRestore(self, index);
        return;
    }

    g_wetRestoreDeferredEvents.fetch_add(1, std::memory_order_relaxed);
}

void ProcessWetMaterialTransitionGameThreadImpl();

void ProcessWetMaterialTransitionGameThread() {
    if (!g_wetMaterialTransitionAvailable.load(std::memory_order_acquire)) return;
    const double tickStart = DualDiagNowMs();
    ServiceWetSwapProbeGameThread(tickStart);
    ProcessWetMaterialTransitionGameThreadImpl();
    NoteWetTickCostGameThread(DualDiagNowMs() - tickStart);
}

void ProcessWetMaterialTransitionGameThreadImpl() {
    if (!g_wetMaterialTransitionAvailable.load(std::memory_order_acquire)) return;

    const bool enabled = g_wetMaterialTransitionEnabled.load(std::memory_order_relaxed);
    
    
    
    
    g_wetMaterialNativeTuningReady.store(enabled, std::memory_order_release);
    if (!enabled && g_wetOriginalRatesCaptured && g_wetTunedPlayerProp) {
        void* currentInstance = CurrentPlayerInstance();
        void* resolvedInstance = g_wetMaterialResolvedInstance.load(std::memory_order_relaxed);
        if (currentInstance && currentInstance == resolvedInstance &&
            TryReadWetPlayerPropTuning(g_wetTunedPlayerProp)) {
            TryWriteWetPlayerPropRates(g_wetTunedPlayerProp, g_wetOriginalDryOffSpeed,
                                       g_wetOriginalWetSpeed);
        }
        g_wetOriginalRatesCaptured = false;
        g_wetTunedPlayerProp = nullptr;
    }

    if (enabled) {
        ServiceWetVisualPrewarmGameThread();
        ServiceWetVisualHiddenDryCleanupGameThread();
        UpdateWetVisualTransitionGameThread();
    } else {
        FlushWetVisualPrewarmToNativeGameThread();
        AbortWetVisualTransition();
    }

    std::array<PendingWetMaterialRestore, 8> due{};
    std::size_t dueCount = 0;
    {
        std::lock_guard<std::mutex> lock(g_wetMaterialMutex);
        const ULONGLONG now = GetTickCount64();
        for (auto& pending : g_pendingWetMaterialRestores) {
            if (!pending.active) continue;
            if (!enabled || now >= pending.dueMs) {
                if (dueCount < due.size()) due[dueCount++] = pending;
                pending = {};
            }
        }
    }

    for (std::size_t i = 0; i < dueCount; ++i) {
        const auto& pending = due[i];
        WetMaterialSwapTableRuntime current{};
        if (!ResolveWetMaterialSwapTable(pending.component, pending.index, &current) ||
            current.componentData != pending.componentData || current.table != pending.table) {
            Log::Detail("Wet material transition: dropped deferred Restore because its component/table lifetime changed");
            continue;
        }
        g_originalMaterialSwapRestore(pending.component, pending.index);
        FinishWetVisualRestore(pending.component, pending.index, pending.table);
        g_wetRestoreCompletedEvents.fetch_add(1, std::memory_order_relaxed);
    }
}

bool ChapterSelectObjectZoneReady() {
    auto** singletonSlot = At<void**>(kRvaObjectZoneManagerSingletonPtr);
    return singletonSlot && IsReadableRange(singletonSlot, sizeof(void*)) && *singletonSlot != nullptr;
}

const char* ResolveChapterSelectUnitName(std::uint16_t unitId) {
    if (!unitId || !g_objectZoneManagerGetZoneName || !ChapterSelectObjectZoneReady())
        return nullptr;
    const char* name = g_objectZoneManagerGetZoneName(static_cast<unsigned int>(unitId));
    return (name && IsReadableRange(name, 1)) ? name : nullptr;
}

bool TryBeginUnitSnapshotBuildGameThread() {
    if (!g_unitControlsAvailable ||
        g_unitSnapshotVersion.load(std::memory_order_acquire) != 0 ||
        g_unitSnapshotBuild.active)
        return false;

    auto** globalSlot = At<void**>(kRvaGlobalInfoPtr);
    if (!globalSlot || !IsReadableRange(globalSlot, sizeof(void*))) {
        g_unitStatusState.store(UnitStatusState::WaitingForData, std::memory_order_release);
        return false;
    }

    auto* global = reinterpret_cast<const std::uint8_t*>(*globalSlot);
    if (!global ||
        !IsReadableRange(global + kGlobalInfoNumReleasesOffset,
                         (kGlobalInfoReleaseListOffset - kGlobalInfoNumReleasesOffset) + sizeof(void*))) {
        g_unitStatusState.store(UnitStatusState::WaitingForData, std::memory_order_release);
        return false;
    }

    const std::uint32_t releaseCount =
        *reinterpret_cast<const std::uint32_t*>(global + kGlobalInfoNumReleasesOffset);
    const auto* releases = *reinterpret_cast<const ChapterSelectReleaseView* const*>(
        global + kGlobalInfoReleaseListOffset);
    if (!releases || releaseCount == 0 || releaseCount > kMaxChapterSelectReleases ||
        !IsReadableRange(releases, static_cast<std::size_t>(releaseCount) * sizeof(ChapterSelectReleaseView))) {
        g_unitStatusState.store(UnitStatusState::WaitingForData, std::memory_order_release);
        return false;
    }

    g_unitSnapshotBuild = UnitSnapshotBuildState{};
    g_unitSnapshotBuild.active = true;
    g_unitSnapshotBuild.releases = releases;
    g_unitSnapshotBuild.releaseCount = releaseCount;
    g_unitSnapshotBuild.next.reserve(512);
    g_unitSnapshotBuild.seen.reserve(512);
    g_unitStatusState.store(UnitStatusState::BuildingList, std::memory_order_release);
    return true;
}

void FinishUnitSnapshotBuildGameThread() {
    if (!g_unitSnapshotBuild.active)
        return;

    if (g_unitSnapshotBuild.next.empty()) {
        g_unitSnapshotBuild = UnitSnapshotBuildState{};
        g_unitStatusState.store(UnitStatusState::WaitingForData, std::memory_order_release);
        g_nextUnitSnapshotProbeMs = GetTickCount64() + 1000;
        return;
    }

    const std::size_t snapshotCount = g_unitSnapshotBuild.next.size();
    {
        std::lock_guard<std::mutex> lock(g_unitSnapshotMutex);
        g_unitSnapshot.swap(g_unitSnapshotBuild.next);
    }
    g_unitSnapshotVersion.fetch_add(1, std::memory_order_release);
    
    
    
    
    g_unitSnapshotBuild.active = false;
    g_unitSnapshotBuild.releases = nullptr;
    g_unitSnapshotBuild.currentSprints = nullptr;
    g_unitSnapshotBuild.currentStories = nullptr;

    if (g_unitStatusState.load(std::memory_order_relaxed) != UnitStatusState::Loading &&
        g_unitStatusState.load(std::memory_order_relaxed) != UnitStatusState::LoadQueued) {
        g_unitStatusState.store(UnitStatusState::Ready, std::memory_order_release);
    }
    Log::Detailf("Unit: incrementally cached %zu native Chapter Select targets", snapshotCount);
}

void ProcessUnitSnapshotBuildGameThread() {
    if (!g_unitControlsAvailable ||
        g_unitSnapshotVersion.load(std::memory_order_acquire) != 0)
        return;

    const ULONGLONG now = GetTickCount64();
    if (!g_unitSnapshotBuild.active) {
        if (now < g_nextUnitSnapshotProbeMs)
            return;
        g_nextUnitSnapshotProbeMs = now + 500;
        if (!TryBeginUnitSnapshotBuildGameThread())
            return;
    }

    
    
    
    auto& liveBuild = g_unitSnapshotBuild;
    const bool releasesReadable =
        liveBuild.releases && liveBuild.releaseCount &&
        IsReadableRange(liveBuild.releases,
                        static_cast<std::size_t>(liveBuild.releaseCount) * sizeof(ChapterSelectReleaseView));
    const bool sprintsReadable =
        !liveBuild.currentSprints || liveBuild.currentSprintCount == 0 ||
        IsReadableRange(liveBuild.currentSprints,
                        static_cast<std::size_t>(liveBuild.currentSprintCount) * sizeof(ChapterSelectSprintView));
    const bool storiesReadable =
        !liveBuild.currentStories || liveBuild.currentStoryCount == 0 ||
        IsReadableRange(liveBuild.currentStories,
                        static_cast<std::size_t>(liveBuild.currentStoryCount) * sizeof(ChapterSelectUserStoryView));
    if (!releasesReadable || !sprintsReadable || !storiesReadable) {
        g_unitSnapshotBuild = UnitSnapshotBuildState{};
        g_unitStatusState.store(UnitStatusState::WaitingForData, std::memory_order_release);
        g_nextUnitSnapshotProbeMs = now + 1000;
        return;
    }

    
    
    constexpr unsigned int kStoriesPerTick = 48;
    constexpr auto kTimeBudget = std::chrono::microseconds(175);
    const auto tickStart = std::chrono::steady_clock::now();
    unsigned int processedStories = 0;

    while (g_unitSnapshotBuild.active && processedStories < kStoriesPerTick &&
           std::chrono::steady_clock::now() - tickStart < kTimeBudget) {
        auto& build = g_unitSnapshotBuild;

        if (build.releaseIndex >= build.releaseCount) {
            FinishUnitSnapshotBuildGameThread();
            return;
        }

        const ChapterSelectReleaseView& release = build.releases[build.releaseIndex];
        if (build.cachedReleaseIndex != build.releaseIndex) {
            build.cachedReleaseIndex = build.releaseIndex;
            build.cachedSprintIndex = std::numeric_limits<std::uint32_t>::max();
            build.sprintIndex = 0;
            build.storyIndex = 0;
            build.currentSprints = nullptr;
            build.currentSprintCount = 0;
            build.currentStories = nullptr;
            build.currentStoryCount = 0;
            build.releaseName[0] = '\0';
            build.sprintName[0] = '\0';

            if (!release.showRelease && !release.showReleaseNonFinal) {
                ++build.releaseIndex;
                continue;
            }
            if (!release.sprintList || release.numSprints == 0 ||
                release.numSprints > kMaxChapterSelectSprintsPerRelease ||
                !IsReadableRange(release.sprintList,
                                 static_cast<std::size_t>(release.numSprints) * sizeof(ChapterSelectSprintView))) {
                ++build.releaseIndex;
                continue;
            }

            build.currentSprints = release.sprintList;
            build.currentSprintCount = release.numSprints;
            CopyReadableCString(release.description, build.releaseName, sizeof(build.releaseName));
        }

        if (build.sprintIndex >= build.currentSprintCount) {
            ++build.releaseIndex;
            build.cachedReleaseIndex = std::numeric_limits<std::uint32_t>::max();
            continue;
        }

        const ChapterSelectSprintView& sprint = build.currentSprints[build.sprintIndex];
        if (build.cachedSprintIndex != build.sprintIndex) {
            build.cachedSprintIndex = build.sprintIndex;
            build.storyIndex = 0;
            build.currentStories = nullptr;
            build.currentStoryCount = 0;
            build.sprintName[0] = '\0';

            if (!sprint.showSprint && !sprint.showSprintNonFinal) {
                ++build.sprintIndex;
                build.cachedSprintIndex = std::numeric_limits<std::uint32_t>::max();
                continue;
            }
            if (!sprint.storyList || sprint.numStories == 0 ||
                sprint.numStories > kMaxChapterSelectStoriesPerSprint ||
                !IsReadableRange(sprint.storyList,
                                 static_cast<std::size_t>(sprint.numStories) * sizeof(ChapterSelectUserStoryView))) {
                ++build.sprintIndex;
                build.cachedSprintIndex = std::numeric_limits<std::uint32_t>::max();
                continue;
            }

            build.currentStories = sprint.storyList;
            build.currentStoryCount = sprint.numStories;
            CopyReadableCString(sprint.description, build.sprintName, sizeof(build.sprintName));
        }

        if (build.storyIndex >= build.currentStoryCount) {
            ++build.sprintIndex;
            build.cachedSprintIndex = std::numeric_limits<std::uint32_t>::max();
            continue;
        }

        const ChapterSelectUserStoryView& story = build.currentStories[build.storyIndex++];
        ++processedStories;
        if (++build.totalStories > kMaxChapterSelectStoriesTotal) {
            FinishUnitSnapshotBuildGameThread();
            return;
        }
        if (!story.unitId)
            continue;

        Features::UnitInfo info{};
        info.unitId = story.unitId;
        info.runnableId = story.runnableId;
        strncpy_s(info.releaseName, build.releaseName, _TRUNCATE);
        strncpy_s(info.sprintName, build.sprintName, _TRUNCATE);
        CopyReadableCString(story.description, info.storyName, sizeof(info.storyName));
        CopyReadableCString(story.runnableName, info.runnableName, sizeof(info.runnableName));

        
        
        std::string key = std::to_string(static_cast<unsigned int>(info.unitId));
        key.push_back('\n');
        key.append(info.runnableName);
        if (build.seen.insert(std::move(key)).second)
            build.next.push_back(info);
    }
}

void ProcessUnitSelectorGameThread() {
    if (!g_unitControlsAvailable)
        return;

    const ULONGLONG now = GetTickCount64();
    ProcessUnitSnapshotBuildGameThread();

    void* netManager = g_netManagerGet ? g_netManagerGet() : nullptr;
    if (g_unitStatusState.load(std::memory_order_relaxed) == UnitStatusState::Loading &&
        netManager && g_netManagerIsLoadLevelPending) {
        const bool pending = g_netManagerIsLoadLevelPending(netManager);
        g_unitLoadObservedPending = g_unitLoadObservedPending || pending;
        if ((!pending && g_unitLoadObservedPending) ||
            (!pending && g_unitLoadIssuedMs != 0 && now - g_unitLoadIssuedMs > 1500)) {
            g_unitLoadObservedPending = false;
            g_unitLoadIssuedMs = 0;
            g_unitStatusState.store(UnitStatusState::Ready, std::memory_order_release);
        }
    }

    PendingUnitLoad request{};
    {
        std::lock_guard<std::mutex> lock(g_unitRequestMutex);
        if (!g_pendingUnitLoad.pending)
            return;
        request = g_pendingUnitLoad;
        g_pendingUnitLoad.pending = false;
    }

    // (v0.9.341: a unit asked for by name has no ID: the cutscene viewer's units)
    const bool byName = !request.unitId && request.unitName[0];
    if (!netManager || !g_netManagerLoadLevel || !g_netManagerIsLoadLevelPending ||
        !g_objectZoneManagerGetZoneName || (!request.unitId && !byName)) {
        g_unitStatusState.store(UnitStatusState::LoadRejected, std::memory_order_release);
        Log::Write("Unit: Chapter Select load rejected because the native managers or Unit ID are unavailable");
        return;
    }

    if (g_netManagerIsLoadLevelPending(netManager)) {
        g_unitStatusState.store(UnitStatusState::LoadRejected, std::memory_order_release);
        Log::Writef("Unit: Chapter Select request for unit=%u rejected because a level transition is already pending",
                    static_cast<unsigned int>(request.unitId));
        return;
    }

    if (!ChapterSelectObjectZoneReady()) {
        g_unitStatusState.store(UnitStatusState::LoadRejected, std::memory_order_release);
        Log::Write("Unit: ObjectZoneManager is not ready for a Chapter Select transition");
        return;
    }

    g_issuedUnitLoad = request;
    const char* runnable = g_issuedUnitLoad.runnableName[0] ? g_issuedUnitLoad.runnableName : nullptr;
    const bool hasRunnable = runnable && std::strcmp(runnable, "null") != 0;
    if (hasRunnable) {
        auto** runnableManagerSlot = At<void**>(kRvaRunnableManagerInstancePtr);
        void* runnableManager =
            (runnableManagerSlot && IsReadableRange(runnableManagerSlot, sizeof(void*)))
                ? *runnableManagerSlot : nullptr;
        if (!runnableManager || !g_runnableManagerSetRunnable || !g_runnableManagerInit) {
            g_unitStatusState.store(UnitStatusState::LoadRejected, std::memory_order_release);
            Log::Writef("Unit: RunnableManager is unavailable for runnable=%s", runnable);
            return;
        }

        g_runnableManagerSetRunnable(runnableManager, runnable);
        g_runnableManagerInit(runnableManager);
    }

    
    
    auto* hardLoadForceSave = At<std::uint8_t*>(kRvaHardLoadForceSave);
    if (!hardLoadForceSave || !IsReadableRange(hardLoadForceSave, sizeof(std::uint8_t))) {
        g_unitStatusState.store(UnitStatusState::LoadRejected, std::memory_order_release);
        Log::Write("Unit: g_hardLoadForceSave is unavailable for Chapter Select");
        return;
    }
    *hardLoadForceSave = 1;

    const char* resolvedUnitName = byName ? request.unitName : ResolveChapterSelectUnitName(request.unitId);
    if (!resolvedUnitName ||
        !CopyReadableCString(resolvedUnitName, g_issuedUnitLoad.unitName,
                             sizeof(g_issuedUnitLoad.unitName))) {
        *hardLoadForceSave = 0;
        g_unitStatusState.store(UnitStatusState::LoadRejected, std::memory_order_release);
        Log::Writef("Unit: failed to resolve ObjectZone name for Chapter Select unit=%u",
                    static_cast<unsigned int>(request.unitId));
        return;
    }

    
    
    
    const bool accepted = g_netManagerLoadLevel(
        netManager,
        g_issuedUnitLoad.unitName,
        true,
        nullptr,
        nullptr,
        0.0f,
        false);

    if (!accepted) {
        *hardLoadForceSave = 0;
        g_unitStatusState.store(UnitStatusState::LoadRejected, std::memory_order_release);
        Log::Writef("Unit: native Chapter Select LoadLevel rejected unit=%u name=%s runnable=%s",
                    static_cast<unsigned int>(request.unitId), g_issuedUnitLoad.unitName,
                    hasRunnable ? runnable : "<none>");
        return;
    }

    g_unitLoadObservedPending = false;
    g_unitLoadIssuedMs = now;
    g_unitStatusState.store(UnitStatusState::Loading, std::memory_order_release);
    Log::Writef("Unit: Chapter Select loading unit=%u name=%s runnable=%s",
                static_cast<unsigned int>(request.unitId), g_issuedUnitLoad.unitName,
                hasRunnable ? runnable : "<none>");
}

void* CurrentSkillOwner() {
    
    
    
    
    auto* owner = reinterpret_cast<std::uint8_t*>(CurrentPlayer());
    if (!owner || !IsReadableRange(owner + kPlayerTraitOwnerContextOffset, sizeof(void*)))
        return nullptr;

    
    
    
    auto* ownerContext = reinterpret_cast<std::uint8_t*>(
        *reinterpret_cast<void**>(owner + kPlayerTraitOwnerContextOffset));
    if (!ownerContext ||
        !IsReadableRange(ownerContext + kPlayerTraitOwnerContextKeyOffset, sizeof(void*)))
        return nullptr;

    static std::atomic_bool loggedOwner{false};
    bool expected = false;
    if (loggedOwner.compare_exchange_strong(expected, true, std::memory_order_relaxed))
        Log::Detailf("Skills: current Player receiver resolved directly at %p", owner);
    return owner;
}

void* PlayerPersistentTraitDataFromPlayer(void* player) {
    if (!player || !g_getPlayerPersistentData) return nullptr;
#if defined(_MSC_VER)
    __try {
        return g_getPlayerPersistentData(player);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        static std::atomic_bool logged{false};
        bool expected = false;
        if (logged.compare_exchange_strong(expected, true, std::memory_order_relaxed))
            Log::Write("Skills: persistent-data accessor raised an exception with a resolved Player receiver; snapshot suppressed");
        return nullptr;
    }
#else
    return g_getPlayerPersistentData(player);
#endif
}

void* SkillPointStateFromPlayer(void* player) {
    if (!player || !g_getSkillPointState) return nullptr;
#if defined(_MSC_VER)
    __try {
        return g_getSkillPointState(player);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        static std::atomic_bool logged{false};
        bool expected = false;
        if (logged.compare_exchange_strong(expected, true, std::memory_order_relaxed))
            Log::Write("Skills: skill-point-state accessor raised an exception with a resolved Player receiver; snapshot suppressed");
        return nullptr;
    }
#else
    return g_getSkillPointState(player);
#endif
}

struct PlayerTraitTableView {
    const std::uint8_t* entries{};
    int count{};
};

bool ResolvePlayerTraitTable(PlayerTraitTableView& out) {
    out = {};
    if (!GameBuild::Base()) return false;

    auto** singletonSlot = reinterpret_cast<void**>(GameBuild::Base() + kRvaPlayerTraitsSingletonPtr);
    if (!IsReadableRange(singletonSlot, sizeof(void*))) return false;
    auto* table = reinterpret_cast<const std::uint8_t*>(*singletonSlot);
    if (!table || !IsReadableRange(table + kPlayerTraitsCountOffset,
                                   kPlayerTraitsEntriesOffset + sizeof(void*) - kPlayerTraitsCountOffset))
        return false;

    const int count = *reinterpret_cast<const int*>(table + kPlayerTraitsCountOffset);
    const auto* entries = *reinterpret_cast<const std::uint8_t* const*>(table + kPlayerTraitsEntriesOffset);
    if (count <= 0 || count > kMaxPlayerTraits || !entries) return false;
    if (!IsReadableRange(entries, static_cast<std::size_t>(count) * kPlayerTraitStride)) return false;

    out.entries = entries;
    out.count = count;
    return true;
}

bool ApplyPersistentTrait(void* persistent, std::uint16_t traitIndex, bool enabled) {
    if (!persistent || traitIndex >= kMaxPlayerTraits) return false;
    auto* bytes = reinterpret_cast<std::uint8_t*>(persistent);
    if (!IsReadableRange(bytes, kPersistentTraitFlagsOffset + static_cast<std::size_t>(traitIndex) + 1))
        return false;

#if defined(_MSC_VER)
    __try {
        if (enabled) {
            if (!g_playerPersistentGiveTrait) return false;
            g_playerPersistentGiveTrait(persistent, traitIndex, false, false, false);
        } else {
            if (!g_playerPersistentRemoveTrait) return false;
            g_playerPersistentRemoveTrait(persistent, traitIndex);
        }
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        Log::Writef("Skills: native persistent trait update raised an exception (trait %u, enabled=%d)",
                    static_cast<unsigned>(traitIndex), enabled ? 1 : 0);
        return false;
    }
#else
    if (enabled) {
        if (!g_playerPersistentGiveTrait) return false;
        g_playerPersistentGiveTrait(persistent, traitIndex, false, false, false);
    } else {
        if (!g_playerPersistentRemoveTrait) return false;
        g_playerPersistentRemoveTrait(persistent, traitIndex);
    }
    return true;
#endif
}

bool SkillSnapshotsEqual(const std::vector<Features::SkillInfo>& a,
                         const std::vector<Features::SkillInfo>& b) {
    if (a.size() != b.size()) return false;
    for (std::size_t i = 0; i < a.size(); ++i) {
        if (a[i].traitIndex != b[i].traitIndex ||
            a[i].category != b[i].category ||
            a[i].enabled != b[i].enabled ||
            std::strcmp(a[i].name, b[i].name) != 0)
            return false;
    }
    return true;
}

bool AdvanceSkillCatalogGameThread(int budget) {
    if (g_skillCatalogComplete) return true;
    if (budget <= 0) return false;

    PlayerTraitTableView table{};
    if (!ResolvePlayerTraitTable(table)) return false;

    
    
    
    
    int processed = 0;
    while (processed < budget && g_skillCatalogCursor < table.count) {
        const int nativeIndex = g_skillCatalogCursor++;
        ++processed;
        const auto* bytes = table.entries + static_cast<std::size_t>(nativeIndex) * kPlayerTraitStride;

        const int category = *reinterpret_cast<const int*>(bytes + kPlayerTraitCategoryOffset);
        if (category != kPlayerTraitCategoryHunter &&
            category != kPlayerTraitCategoryBrawler &&
            category != kPlayerTraitCategorySurvivor)
            continue;

        const std::uint16_t traitIndex = static_cast<std::uint16_t>(nativeIndex);
        Features::SkillInfo info{};
        info.traitIndex = traitIndex;
        info.category = category;
        info.enabled = false;

        const char* debugName =
            *reinterpret_cast<const char* const*>(bytes + kPlayerTraitDebugNameOffset);
        if (!CopyReadableCString(debugName, info.name, sizeof(info.name)))
            std::snprintf(info.name, sizeof(info.name), "Skill %u",
                          static_cast<unsigned>(traitIndex));
        g_skillCatalog.push_back(info);
    }

    if (g_skillCatalogCursor >= table.count)
        g_skillCatalogComplete = true;

    if (g_skillCatalogComplete) {
        int survivorCount = 0;
        int hunterCount = 0;
        int brawlerCount = 0;
        std::array<bool, kMaxPlayerTraits> seenIndices{};
        int duplicateIndices = 0;
        for (const auto& info : g_skillCatalog) {
            if (info.category == kPlayerTraitCategorySurvivor) ++survivorCount;
            else if (info.category == kPlayerTraitCategoryHunter) ++hunterCount;
            else if (info.category == kPlayerTraitCategoryBrawler) ++brawlerCount;
            if (seenIndices[info.traitIndex]) ++duplicateIndices;
            seenIndices[info.traitIndex] = true;
        }
        Log::Detailf("Skills: cached trait catalog (%zu editable skills from %d native entries; Survivor=%d Hunter=%d Brawler=%d duplicate-list-indices=%d; direct-table path)",
                    g_skillCatalog.size(), g_skillCatalogCursor, survivorCount, hunterCount,
                    brawlerCount, duplicateIndices);
        g_forceSkillSnapshot.store(true, std::memory_order_release);
    }
    return g_skillCatalogComplete;
}

void RefreshSkillSnapshotGameThread() {
    if (!g_skillControlsAvailable) return;

    void* player = CurrentPlayer();
    if (!player) {
        g_skillPointCount.store(-1, std::memory_order_relaxed);
        {
            std::lock_guard<std::mutex> lock(g_skillMutex);
            if (!g_skillSnapshot.empty()) {
                g_skillSnapshot.clear();
                g_skillSnapshotVersion.fetch_add(1, std::memory_order_release);
            }
        }
        g_skillStatusState.store(SkillStatusState::NoPlayer, std::memory_order_release);
        return;
    }

    void* playerReceiver = CurrentSkillOwner();
    if (!playerReceiver) {
        static std::atomic_bool loggedOwnerFailure{false};
        bool expected = false;
        if (loggedOwnerFailure.compare_exchange_strong(expected, true, std::memory_order_relaxed))
            Log::Detail("Skills: current Player receiver is not ready for persistent skill access yet");
        g_skillPointCount.store(-1, std::memory_order_relaxed);
        g_skillStatusState.store(SkillStatusState::NoPersistentData, std::memory_order_release);
        return;
    }

    auto* skillState = reinterpret_cast<std::uint8_t*>(SkillPointStateFromPlayer(playerReceiver));
    auto* pointField = skillState
        ? reinterpret_cast<int*>(skillState + kSkillPointCountOffset)
        : nullptr;
    if (!pointField || !IsReadableRange(pointField, sizeof(*pointField))) {
        g_skillPointCount.store(-1, std::memory_order_relaxed);
        g_skillStatusState.store(SkillStatusState::NoPersistentData, std::memory_order_release);
        return;
    }

    const int points = *pointField;
    if (points < 0 || points > 1000000) {
        Log::Writef("Skills: rejecting implausible skill-point count %d", points);
        g_skillPointCount.store(-1, std::memory_order_relaxed);
        g_skillStatusState.store(SkillStatusState::NoPersistentData, std::memory_order_release);
        return;
    }
    g_skillPointCount.store(points, std::memory_order_relaxed);

    void* persistent = PlayerPersistentTraitDataFromPlayer(playerReceiver);
    if (!persistent ||
        !IsReadableRange(reinterpret_cast<std::uint8_t*>(persistent) + kPersistentTraitFlagsOffset,
                         static_cast<std::size_t>(kMaxPlayerTraits))) {
        static std::atomic_bool loggedPersistentFailure{false};
        bool expected = false;
        if (loggedPersistentFailure.compare_exchange_strong(expected, true, std::memory_order_relaxed))
            Log::Detail("Skills: current player resolved but persistent trait bytes are not available yet");
        g_skillStatusState.store(SkillStatusState::NoPersistentData, std::memory_order_release);
        return;
    }

    static std::atomic_bool loggedSafeSnapshot{false};
    bool expectedSnapshot = false;
    if (loggedSafeSnapshot.compare_exchange_strong(expectedSnapshot, true, std::memory_order_relaxed))
        Log::Detailf("Skills: lightweight persistent snapshots active (skill points=%d)", points);

    if (!g_skillCatalogComplete) {
        g_skillStatusState.store(SkillStatusState::NoTraitTable, std::memory_order_release);
        g_lastSkillSnapshot = std::chrono::steady_clock::now();
        return;
    }

    
    
    
    std::vector<Features::SkillInfo> fresh = g_skillCatalog;
    auto* persistentBytes = reinterpret_cast<const std::uint8_t*>(persistent);
    for (auto& info : fresh) {
        info.enabled = persistentBytes[kPersistentTraitFlagsOffset +
                                       static_cast<std::size_t>(info.traitIndex)] != 0;
    }

    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(g_skillMutex);
        if (!SkillSnapshotsEqual(g_skillSnapshot, fresh)) {
            g_skillSnapshot.swap(fresh);
            changed = true;
        }
    }
    if (changed)
        g_skillSnapshotVersion.fetch_add(1, std::memory_order_release);

    g_lastSkillSnapshot = std::chrono::steady_clock::now();
    g_skillStatusState.store(g_skillCatalog.empty() ? SkillStatusState::NoTraitTable
                                                     : SkillStatusState::Ready,
                             std::memory_order_release);
}

void ProcessSkillsGameThread() {
    if (!g_skillControlsAvailable) return;

    const bool editorActive = g_skillEditorActive.load(std::memory_order_relaxed);
    const bool needsCatalogPrewarm = !g_skillCatalogComplete;
    const bool hasPointMutation = g_pendingSkillPointDelta.load(std::memory_order_relaxed) != 0;
    const bool hasToggleMutation = g_hasPendingSkillToggles.load(std::memory_order_relaxed);
    const bool forcedSnapshot = g_forceSkillSnapshot.load(std::memory_order_relaxed);

    
    
    if (!editorActive && !needsCatalogPrewarm && !hasPointMutation &&
        !hasToggleMutation && !forcedSnapshot)
        return;

    int pointDelta = g_pendingSkillPointDelta.exchange(0, std::memory_order_acq_rel);
    std::vector<PendingSkillToggle> toggles;
    if (g_hasPendingSkillToggles.exchange(false, std::memory_order_acq_rel)) {
        std::lock_guard<std::mutex> lock(g_skillMutex);
        if (!g_pendingSkillToggles.empty())
            toggles.swap(g_pendingSkillToggles);
    }

    const bool hasMutation = pointDelta != 0 || !toggles.empty();
    if (hasMutation) {
        const bool hasPlayer = CurrentPlayer() != nullptr;
        void* playerReceiver = hasPlayer ? CurrentSkillOwner() : nullptr;
        bool applied = hasPlayer && playerReceiver != nullptr;

        if (hasPlayer && playerReceiver && pointDelta != 0) {
            auto* skillState = reinterpret_cast<std::uint8_t*>(SkillPointStateFromPlayer(playerReceiver));
            auto* pointField = skillState
                ? reinterpret_cast<int*>(skillState + kSkillPointCountOffset)
                : nullptr;
            if (!pointField || !IsWritableRange(pointField, sizeof(*pointField)) ||
                *pointField < 0 || *pointField > 1000000) {
                applied = false;
            } else {
                long long desired = static_cast<long long>(*pointField) + static_cast<long long>(pointDelta);
                desired = std::clamp<long long>(desired, 0, std::numeric_limits<int>::max());
                *pointField = static_cast<int>(desired);
            }
        }

        if (!toggles.empty()) {
            void* persistent = (hasPlayer && playerReceiver) ? PlayerPersistentTraitDataFromPlayer(playerReceiver) : nullptr;
            if (!persistent) {
                applied = false;
            } else {
                for (const auto& pending : toggles) {
                    if (!ApplyPersistentTrait(persistent, pending.traitIndex, pending.enabled))
                        applied = false;
                }
            }
        }

        g_skillStatusState.store(applied ? SkillStatusState::UpdateApplied : SkillStatusState::UpdateRejected,
                                 std::memory_order_release);
        g_forceSkillSnapshot.store(true, std::memory_order_release);
    }

    
    
    
    
    if (!g_skillCatalogComplete)
        AdvanceSkillCatalogGameThread(kSkillCatalogEntriesPerFrame);

    const bool force = g_forceSkillSnapshot.exchange(false, std::memory_order_acq_rel);
    const auto now = std::chrono::steady_clock::now();
    if (force || (editorActive &&
        (g_lastSkillSnapshot.time_since_epoch().count() == 0 ||
         now - g_lastSkillSnapshot >= kSkillDynamicRefreshInterval))) {
        RefreshSkillSnapshotGameThread();
    }
}

float CurrentHealthHitPoints(void* health) {
    if (!health || !IsReadableRange(health, static_cast<std::size_t>(kHealthDataSetRuntimeOffset) + sizeof(void*)))
        return -1.0f;
    void* dataSet = *reinterpret_cast<void**>(reinterpret_cast<std::uint8_t*>(health) + kHealthDataSetRuntimeOffset);
    if (!dataSet || !IsReadableRange(reinterpret_cast<std::uint8_t*>(dataSet) + kHealthDataSetFloatHpOffset, sizeof(float)))
        return -1.0f;
    const float hp = *reinterpret_cast<const float*>(reinterpret_cast<const std::uint8_t*>(dataSet) + kHealthDataSetFloatHpOffset);
    return std::isfinite(hp) ? hp : -1.0f;
}

float MaxHealthHitPoints(void* health) {
    if (!health || !IsReadableRange(reinterpret_cast<std::uint8_t*>(health) + kHealthMaxHitPointsRuntimeOffset, sizeof(int)))
        return -1.0f;
    const int maxHp = *reinterpret_cast<const int*>(reinterpret_cast<const std::uint8_t*>(health) + kHealthMaxHitPointsRuntimeOffset);
    if (maxHp <= 0 || maxHp > 100000000) return -1.0f;
    return static_cast<float>(maxHp);
}

void RestoreInfiniteHealthNow(void* health) {
    if (!g_setHitPoints || !health) return;
    const float maxHp = MaxHealthHitPoints(health);
    if (!(maxHp > 0.0f)) return;
    const float currentHp = CurrentHealthHitPoints(health);
    if (currentHp < 0.0f || currentHp + 0.0001f < maxHp)
        g_setHitPoints(health, maxHp);
}






void RestoreInfiniteHealthFromDamageHook(void* health) {
    if (!g_setHitPoints || !health) return;
    const int maxHp = *reinterpret_cast<const int*>(
        reinterpret_cast<const std::uint8_t*>(health) + kHealthMaxHitPointsRuntimeOffset);
    if (maxHp > 0 && maxHp <= 100000000)
        g_setHitPoints(health, static_cast<float>(maxHp));
}

void __fastcall HookHealthApplyDamage(void* health, NativeDamageData* damage) {
    if (!g_originalHealthApplyDamage) return;

    if (g_trainerInstantKillInFlight || !health || !damage) {
        g_originalHealthApplyDamage(health, damage);
        return;
    }

    if (g_dualWieldExperimental.load(std::memory_order_relaxed) &&
        g_dualWieldShotPhase != DualWieldShotPhase::None) {
        float dualDamageAmount = 0.0f;
        int dualDamageType = 0;
        std::memcpy(&dualDamageAmount, damage->bytes + 0x00, sizeof(dualDamageAmount));
        std::memcpy(&dualDamageType, damage->bytes + 0x04, sizeof(dualDamageType));
        auto& counter = (g_dualWieldShotPhase == DualWieldShotPhase::Secondary)
            ? g_dualWieldSecondaryDamageEvents : g_dualWieldPrimaryDamageEvents;
        const std::uint64_t eventIndex = counter.fetch_add(1, std::memory_order_relaxed) + 1u;
        if (eventIndex <= 12u) {
            Log::Detailf("Dual wield Stage 34 damage: phase=%s health=%p amount=%.3f type=%d event=%llu",
                        g_dualWieldShotPhase == DualWieldShotPhase::Secondary ? "secondary" : "primary",
                        health, static_cast<double>(dualDamageAmount), dualDamageType,
                        static_cast<unsigned long long>(eventIndex));
        } else if (eventIndex == 13u) {
            Log::Detailf("Dual wield Stage 34 damage: %s logging suppressed after 12 events",
                        g_dualWieldShotPhase == DualWieldShotPhase::Secondary ? "secondary" : "primary");
        }
    }

    const auto healthAddress = reinterpret_cast<std::uintptr_t>(health);

    
    
    
    
    
    if (g_oneHitKill.load(std::memory_order_relaxed)) {
        const auto playerHealth = g_oneHitKillPlayerHealth.load(std::memory_order_acquire);
        if (playerHealth && healthAddress != playerHealth) {
            float damageAmount = 0.0f;
            std::memcpy(&damageAmount, damage->bytes + 0x00, sizeof(damageAmount));
            if (std::isfinite(damageAmount) && damageAmount > 0.0f) {
                const int maxHp = *reinterpret_cast<const int*>(
                    reinterpret_cast<const std::uint8_t*>(health) + kHealthMaxHitPointsRuntimeOffset);
                if (maxHp > 0 && maxHp <= 100000000) {
                    NativeDamageData lethalDamage = *damage;
                    
                    
                    const float lethalAmount = std::max(
                        damageAmount,
                        std::min(static_cast<float>(maxHp) * 1024.0f, 1.0e12f));
                    WriteDamageField(lethalDamage, 0x00, lethalAmount);
                    g_originalHealthApplyDamage(health, &lethalDamage);
                    return;
                }
            }
        }
    }

    const bool infinite = g_infiniteHealth.load(std::memory_order_relaxed);
    const auto playerHealth = g_infiniteHealthComponent.load(std::memory_order_acquire);
    if (!infinite || healthAddress != playerHealth) {
        g_originalHealthApplyDamage(health, damage);
        return;
    }

    int damageType = 0;
    float damageAmount = 0.0f;
    std::memcpy(&damageAmount, damage->bytes + 0x00, sizeof(damageAmount));
    std::memcpy(&damageType, damage->bytes + 0x04, sizeof(damageType));

    
    
    
    
    if (damageType == kDamageTypeInstantKill) {
        RestoreInfiniteHealthFromDamageHook(health);
        return;
    }

    NativeDamageData safeDamage = *damage;
    if (std::isfinite(damageAmount) && damageAmount > 0.01f) {
        const float tinyDamage = 0.01f;
        WriteDamageField(safeDamage, 0x00, tinyDamage);
    }
    g_originalHealthApplyDamage(health, &safeDamage);
    RestoreInfiniteHealthFromDamageHook(health);
}
















struct InventoryMapNodeLite {
    InventoryMapNodeLite* next{};
    std::uint32_t key{};
    std::uint16_t value{};
    std::uint16_t padding{};
};
static_assert(sizeof(InventoryMapNodeLite) == 0x10);
static_assert(offsetof(InventoryMapNodeLite, key) == 0x08);
static_assert(offsetof(InventoryMapNodeLite, value) == 0x0C);

struct InventoryMapView {
    InventoryMapNodeLite** buckets{};
    std::uint64_t bucketCount{};
    std::uint64_t size{};
    std::uint64_t tableSize{};
    std::uint8_t allowResize{};
};
static_assert(sizeof(InventoryMapView) == 0x28);

struct InventoryValueRef {
    std::uint32_t key{};
    std::uint16_t* value{};
};

bool ReadInventoryMap(void* mapAddress, std::vector<InventoryValueRef>& out) {
    out.clear();
    if (!mapAddress || !IsReadableRange(mapAddress, sizeof(InventoryMapView))) return false;
    const auto* map = reinterpret_cast<const InventoryMapView*>(mapAddress);
    if (map->allowResize > 1 || map->bucketCount > kMaxInventoryMapBuckets ||
        map->size > kMaxInventoryMapEntries || map->tableSize > (1ull << 20))
        return false;
    if (map->bucketCount == 0)
        return map->size == 0;
    if (!map->buckets || !IsReadableRange(map->buckets, static_cast<std::size_t>(map->bucketCount) * sizeof(void*)))
        return false;

    out.reserve(static_cast<std::size_t>(map->size));
    std::size_t visited = 0;
    for (std::uint64_t bucket = 0; bucket < map->bucketCount; ++bucket) {
        InventoryMapNodeLite* node = map->buckets[bucket];
        std::size_t chainGuard = 0;
        while (node) {
            if (++chainGuard > kMaxInventoryMapEntries || ++visited > kMaxInventoryMapEntries)
                return false;
            
            
            
            out.push_back({node->key, &node->value});
            node = node->next;
        }
    }
    return visited == map->size;
}







struct InventoryItemMapNodeLite {
    InventoryItemMapNodeLite* next{};        
    std::uint32_t key{};                     
    std::uint32_t pairPadding{};             
    std::uint8_t hidden{};                   
    std::uint8_t itemPadding[3]{};            
    std::uint32_t objectId{};                
    std::uint32_t instanceCount{};           
    std::uint32_t primaryInstanceCount{};    
};
static_assert(offsetof(InventoryItemMapNodeLite, key) == 0x08);
static_assert(offsetof(InventoryItemMapNodeLite, objectId) == 0x14);
static_assert(offsetof(InventoryItemMapNodeLite, instanceCount) == 0x18);
static_assert(offsetof(InventoryItemMapNodeLite, primaryInstanceCount) == 0x1C);

struct InventoryItemRef {
    std::uint32_t inventoryId{};
    std::uint32_t objectId{};
    std::uint32_t instanceCount{};
    std::uint32_t primaryInstanceCount{};
};

struct InventoryItemMapView {
    InventoryItemMapNodeLite** buckets{};
    std::uint64_t bucketCount{};
    std::uint64_t size{};
    std::uint64_t tableSize{};
    std::uint8_t allowResize{};
};
static_assert(sizeof(InventoryItemMapView) == 0x28);

