void RecordPresentTiming(std::uint64_t frameworkMicroseconds, std::uint64_t presentMicroseconds) {
    g_presentCount.fetch_add(1, std::memory_order_relaxed);
    g_presentOursUsSum.fetch_add(frameworkMicroseconds, std::memory_order_relaxed);
    g_presentCallUsSum.fetch_add(presentMicroseconds, std::memory_order_relaxed);
    AtomicMaxU64(g_presentOursUsMax, frameworkMicroseconds);
    AtomicMaxU64(g_presentCallUsMax, presentMicroseconds);
    if (frameworkMicroseconds >= 4000) g_presentOursSlow.fetch_add(1, std::memory_order_relaxed);
}

void RecordLoadingPresent(unsigned int requestedSyncInterval, unsigned int appliedSyncInterval,
                          bool usedDoNotWait, bool wouldBlockDrop, bool otherFailure,
                          std::uint64_t elapsedNanoseconds) {
    if (!g_loadingProfileActive.load(std::memory_order_acquire))
        return;
    g_loadingPresentCalls.fetch_add(1, std::memory_order_relaxed);
    if (requestedSyncInterval == 0)
        g_loadingPresentSync0Calls.fetch_add(1, std::memory_order_relaxed);
    else if (requestedSyncInterval == 1)
        g_loadingPresentSync1Calls.fetch_add(1, std::memory_order_relaxed);
    else
        g_loadingPresentSyncOtherCalls.fetch_add(1, std::memory_order_relaxed);
    if (requestedSyncInterval != appliedSyncInterval && appliedSyncInterval == 0)
        g_loadingPresentForcedNoSyncCalls.fetch_add(1, std::memory_order_relaxed);
    if (usedDoNotWait) {
        g_loadingPresentDoNotWaitCalls.fetch_add(1, std::memory_order_relaxed);
        if (wouldBlockDrop)
            g_loadingPresentWouldBlockDrops.fetch_add(1, std::memory_order_relaxed);
        else if (otherFailure)
            g_loadingPresentOtherFailures.fetch_add(1, std::memory_order_relaxed);
        else
            g_loadingPresentDoNotWaitSuccessCalls.fetch_add(1, std::memory_order_relaxed);
    }
    g_loadingPresentNanoseconds.fetch_add(elapsedNanoseconds, std::memory_order_relaxed);
    AtomicMax(g_loadingPresentMaxNanoseconds, elapsedNanoseconds);
}

bool GetLoadingProfile(LoadingProfile& out) {
    if (!LoadingProfilerAvailable()) {
        out = {};
        return false;
    }

    {
        std::lock_guard<std::mutex> lock(g_loadingProfileMutex);
        out = g_loadingProfileSnapshot;
    }

    if (g_loadingProfileActive.load(std::memory_order_acquire)) {
        out.available = true;
        out.active = true;
        out.completed = false;
        out.sessionId = g_loadingProfileSessionId.load(std::memory_order_acquire);
        const std::uint64_t now = QpcNow();
        const std::uint64_t start = g_loadingProfileStartQpc.load(std::memory_order_acquire);
        out.elapsedSeconds = QpcSeconds(now >= start ? now - start : 0);
        out.worldLoadUnitCalls = g_loadingWorldLoadUnitCalls.load(std::memory_order_relaxed);
        out.worldLoadUnitAggregateSeconds = QpcSeconds(g_loadingWorldLoadUnitTicks.load(std::memory_order_relaxed));
        out.worldLoadUnitMaxMs = QpcSeconds(g_loadingWorldLoadUnitMaxTicks.load(std::memory_order_relaxed)) * 1000.0;
        out.resolveDataCalls = g_loadingResolveDataCalls.load(std::memory_order_relaxed);
        out.resolveDataBytes = g_loadingResolveDataBytes.load(std::memory_order_relaxed);
        out.resolveDataAggregateSeconds = QpcSeconds(g_loadingResolveDataTicks.load(std::memory_order_relaxed));
        out.resolveDataMaxMs = QpcSeconds(g_loadingResolveDataMaxTicks.load(std::memory_order_relaxed)) * 1000.0;
        out.resolveDoneCalls = g_loadingResolveDoneCalls.load(std::memory_order_relaxed);
        out.fastLoadingEnabledForSession = g_loadingFastModeSession.load(std::memory_order_relaxed);
        out.fastLoadingSleepShortenedCalls = g_fastLoadingSleepShortenedCalls.load(std::memory_order_relaxed);
        out.fastLoadingSleepRequestedMs = g_fastLoadingSleepRequestedMs.load(std::memory_order_relaxed);
        out.loadingPresentCalls = g_loadingPresentCalls.load(std::memory_order_relaxed);
        out.loadingPresentSync0Calls = g_loadingPresentSync0Calls.load(std::memory_order_relaxed);
        out.loadingPresentSync1Calls = g_loadingPresentSync1Calls.load(std::memory_order_relaxed);
        out.loadingPresentSyncOtherCalls = g_loadingPresentSyncOtherCalls.load(std::memory_order_relaxed);
        out.loadingPresentForcedNoSyncCalls = g_loadingPresentForcedNoSyncCalls.load(std::memory_order_relaxed);
        out.loadingPresentAggregateSeconds = static_cast<double>(g_loadingPresentNanoseconds.load(std::memory_order_relaxed)) / 1000000000.0;
        out.loadingPresentMaxMs = static_cast<double>(g_loadingPresentMaxNanoseconds.load(std::memory_order_relaxed)) / 1000000.0;
        out.fastLoadingAggressiveRendererForSession =
            g_loadingAggressiveRendererSession.load(std::memory_order_relaxed);
        out.fastLoadingRendererOriginalSetting =
            g_fastLoadingRendererOriginalSetting.load(std::memory_order_relaxed);
        out.fastLoadingRendererOriginalMode =
            g_fastLoadingRendererOriginalMode.load(std::memory_order_relaxed);
        out.fastLoadingRendererLastSetting =
            g_fastLoadingRendererLastSetting.load(std::memory_order_relaxed);
        out.fastLoadingRendererLastMode =
            g_fastLoadingRendererLastMode.load(std::memory_order_relaxed);
        out.fastLoadingRendererBeginFrameCalls =
            g_fastLoadingRendererBeginFrameCalls.load(std::memory_order_relaxed);
        out.fastLoadingRendererOverrideWrites =
            g_fastLoadingRendererOverrideWrites.load(std::memory_order_relaxed);
        out.fastLoadingRendererRestoreWrites =
            g_fastLoadingRendererRestoreWrites.load(std::memory_order_relaxed);
        
        
        out.processReadOperations = 0;
        out.processReadBytes = 0;
        out.processWriteBytes = 0;
        out.processUserCpuSeconds = 0.0;
        out.processKernelCpuSeconds = 0.0;
        out.cpuCoreEquivalent = 0.0;
    }
    return true;
}

