const char* DualWieldStatus() {
    thread_local char text[256]{};
    if (!g_dualWieldExperimental.load(std::memory_order_relaxed)) return "off";
    if (!g_dualWieldSecondaryHandle.load(std::memory_order_acquire)) {
        if (g_dualWieldBirthOwned.load(std::memory_order_acquire)) return "creating the offhand pistol...";
        if (g_dualWieldWaitingForHolster.load(std::memory_order_relaxed))
            return "armed; holster the pistol once to create the offhand pistol";
        return "armed; equip a pistol (it is doubled while holstered)";
    }
    std::size_t nodes = 0;
    AcquireSRWLockShared(&g_dualNodeLock);
    nodes = g_dualNodeRecords.size();
    ReleaseSRWLockShared(&g_dualNodeLock);
    std::snprintf(text, sizeof(text),
                  "offhand %s | left holster %s | clips %s (%zu nodes) | muzzle FX L native %llu, fallback %llu, failed %llu"
                  " | other gun's fire anim kept %u times",
                  g_dualWieldNativeItemActive.load(std::memory_order_acquire) ? "native"
                      : (g_dualWieldNativeOffhandFire.load(std::memory_order_acquire) ? "pending" : "cosmetic"),
                  g_dualLeftHolsterActive.load(std::memory_order_acquire) ? "on" : "off",
                  g_dualNodeActive.load(std::memory_order_acquire) ? "dual" : "single", nodes,
                  static_cast<unsigned long long>(g_dualFxNativeLeft.load(std::memory_order_relaxed)),
                  static_cast<unsigned long long>(g_dualFxFallbackLeft.load(std::memory_order_relaxed)),
                  static_cast<unsigned long long>(g_dualFxFailedLeft.load(std::memory_order_relaxed)),
                  g_dualGunNodesKept.load(std::memory_order_relaxed));
    return text;
}

