void SetDualWieldExperimentalEnabled(bool enabled) {
    if (enabled && !DualWieldExperimentalAvailable()) return;
    const bool old = g_dualWieldExperimental.exchange(enabled, std::memory_order_acq_rel);
    if (old != enabled) {
        if (enabled) {
            g_dualWieldPrimaryShots.store(0, std::memory_order_relaxed);
            g_dualWieldSecondaryShots.store(0, std::memory_order_relaxed);
            g_dualWieldPrimaryDamageEvents.store(0, std::memory_order_relaxed);
            g_dualWieldSecondaryDamageEvents.store(0, std::memory_order_relaxed);
            g_dualWieldLastZoneId.store(0, std::memory_order_relaxed);
            g_dualWieldPrimaryHandle.store(0, std::memory_order_relaxed);
            g_dualWieldPrimaryMember.store(0, std::memory_order_relaxed);
            g_dualWieldSecondaryMember.store(0, std::memory_order_relaxed);
            g_dualWieldPostAttachFixups.store(0, std::memory_order_relaxed);
            g_dualWieldLeftWristBone.store(-1, std::memory_order_relaxed);
            g_dualWieldLeftGrabPivotBone.store(-1, std::memory_order_relaxed);
            g_dualWieldLeftGrabJointBone.store(-1, std::memory_order_relaxed);
            g_dualWieldRightGrabPivotBone.store(-1, std::memory_order_relaxed);
            g_dualWieldRightGrabJointBone.store(-1, std::memory_order_relaxed);
            g_dualWieldInventoryMemberIndex.store(-1, std::memory_order_relaxed);
            g_dualWieldWeaponComponentIndex.store(-1, std::memory_order_relaxed);
            g_dualWieldAttachState.store(3, std::memory_order_relaxed);
            g_dualWieldAttachStateInfo.store(0, std::memory_order_relaxed);
            
            g_dualWieldSecondaryCosmeticMaskValid.store(false, std::memory_order_release);
            g_dualWieldSecondaryCosmeticMask.store(0, std::memory_order_relaxed);
            g_dualAnimRestoreRequested.store(false, std::memory_order_release);
            g_dualAnimScanResetRequested.store(true, std::memory_order_release);
            g_dualAnimNextScanMs.store(0, std::memory_order_relaxed);
            
            
            
            g_dualAnimApplyRequested.store(false, std::memory_order_release);
            g_dualWieldNativeItemActive.store(false, std::memory_order_release);
            g_dualWieldNativeItemSetupRequested.store(false, std::memory_order_release);
            g_dualWieldNativeItemNextRetryMs.store(0, std::memory_order_relaxed);
            g_dualWieldNativeShotsObserved.store(0, std::memory_order_relaxed);
            g_dualWieldSequentialResetSuppressions.store(0, std::memory_order_relaxed);
            g_dualWieldLastSuccessfulUseSlot.store(0xFFFFFFFFu, std::memory_order_relaxed);
            g_dualWieldDualFireDataInjections.store(0, std::memory_order_relaxed);
            g_dualWieldGraphRefreshRequested.store(false, std::memory_order_release);
            g_dualWieldPlayerRestoreRequested.store(false, std::memory_order_release);
            g_dualWieldBlendLastTickMs.store(0, std::memory_order_relaxed);
            g_dualWieldBlendActiveLogged.store(false, std::memory_order_relaxed);
            g_dualLeftHolsterRestoreRequested.store(false, std::memory_order_release);
            g_dualLeftHolsterAwayOverrides.store(0, std::memory_order_relaxed);
            g_dualFxNativeLeft.store(0, std::memory_order_relaxed);
            g_dualFxNativeRight.store(0, std::memory_order_relaxed);
            g_dualFxFallbackLeft.store(0, std::memory_order_relaxed);
            g_dualFxFailedLeft.store(0, std::memory_order_relaxed);
            g_dualWieldWaitingForHolster.store(false, std::memory_order_relaxed);
            g_dualWieldArmNextMs = 0;
            OpenDualDiagWindow(30);
        } else {
            g_dualLeftHolsterRestoreRequested.store(true, std::memory_order_release);
            g_dualWieldNativeItemSetupRequested.store(false, std::memory_order_release);
            g_dualAnimApplyRequested.store(false, std::memory_order_release);
            g_dualAnimScanResetRequested.store(true, std::memory_order_release);
            g_dualAnimRestoreRequested.store(true, std::memory_order_release);
            g_dualWieldGraphRefreshRequested.store(false, std::memory_order_release);
            g_dualWieldPlayerRestoreRequested.store(true, std::memory_order_release);
            RequestDualWieldSecondaryCleanup();
        }
        Log::Detail(enabled ? "Dual wield Stage 36: enabled; the offhand pistol is created while the pistol is holstered "
                             "(marker-14 offhand, native two-primary Sequential Item, node-level dual clips)"
                           : "Dual wield Stage 34: disabled; native Item restore + secondary clone cleanup queued");
    }
}

