int CopyEquipment(EquipmentInfo* out, int capacity) {
    if (!g_equipmentControlsAvailable || !out || capacity <= 0) return 0;
    std::lock_guard<std::mutex> lock(g_equipmentMutex);
    const int count = std::min<int>(capacity, static_cast<int>(g_equipmentSnapshot.size()));
    for (int i = 0; i < count; ++i) out[i] = g_equipmentSnapshot[static_cast<std::size_t>(i)];
    return count;
}

bool QueueEquipment(int recipe, bool give) {
    if (!g_equipmentControlsAvailable || recipe < -1 || recipe >= static_cast<int>(kMaxCraftingRecipes)) return false;
    std::lock_guard<std::mutex> lock(g_equipmentMutex);
    g_pendingEquipment.emplace_back(recipe, give);
    g_hasPendingEquipment.store(true, std::memory_order_release);
    g_equipmentStatus.store(4, std::memory_order_relaxed);
    return true;
}

