unsigned int WeaponVariantCount(WeaponClass weaponClass) {
    const int index = static_cast<int>(weaponClass);
    if (!g_weaponControlsAvailable || index < 0 || index >= 4) return 0;
    std::lock_guard<std::mutex> lock(g_weaponSnapshotMutex);
    return static_cast<unsigned int>(g_weaponSnapshot[static_cast<std::size_t>(index)].size());
}

bool GetWeaponVariantInfo(WeaponClass weaponClass, unsigned int index,
                          WeaponVariantInfo& out) {
    const int classIndex = static_cast<int>(weaponClass);
    if (!g_weaponControlsAvailable || classIndex < 0 || classIndex >= 4) return false;
    std::lock_guard<std::mutex> lock(g_weaponSnapshotMutex);
    const auto& variants = g_weaponSnapshot[static_cast<std::size_t>(classIndex)];
    if (index >= variants.size()) return false;
    out = variants[index];
    return true;
}

bool QueueWeaponVariantCommand(unsigned int objectZoneId, WeaponCommandAction action) {
    if (!g_weaponControlsAvailable || objectZoneId == 0 || objectZoneId > 0x1FFFFFFFu)
        return false;
    const unsigned int packedUnsigned = (objectZoneId << 2) | static_cast<unsigned int>(action);
    if (packedUnsigned > static_cast<unsigned int>(std::numeric_limits<int>::max())) return false;
    const int packed = static_cast<int>(packedUnsigned);
    int expected = -1;
    if (!g_pendingWeaponCommand.compare_exchange_strong(expected, packed,
            std::memory_order_acq_rel, std::memory_order_relaxed))
        return false;
    g_weaponRuntimeStatus.store(WeaponRuntimeStatus::Applying, std::memory_order_release);
    return true;
}

bool RequestEquipWeaponVariant(unsigned int objectZoneId) {
    return QueueWeaponVariantCommand(objectZoneId, WeaponCommandAction::Equip);
}

bool RequestUnlockWeaponVariant(unsigned int objectZoneId) {
    return QueueWeaponVariantCommand(objectZoneId, WeaponCommandAction::Unlock);
}

bool RequestRemoveWeaponVariant(unsigned int objectZoneId) {
    return QueueWeaponVariantCommand(objectZoneId, WeaponCommandAction::Remove);
}


