bool RequestSetCardEnabled(unsigned int cardHash, bool enabled) {
    if (!g_cardControlsAvailable || cardHash == 0) return false;
    const std::uint64_t packed = (static_cast<std::uint64_t>(cardHash) << 1) |
                                 static_cast<std::uint64_t>(enabled ? 1u : 0u);
    std::uint64_t expected = kNoPendingCardCommand;
    if (!g_pendingCardCommand.compare_exchange_strong(expected, packed,
            std::memory_order_acq_rel, std::memory_order_relaxed))
        return false;

    
    
    
    {
        std::lock_guard<std::mutex> lock(g_cardSnapshotMutex);
        for (auto& card : g_cardSnapshot) {
            if (card.cardHash == cardHash) {
                card.active = enabled;
                break;
            }
        }
    }
    g_cardSnapshotVersion.fetch_add(1, std::memory_order_release);
    g_cardRuntimeStatus.store(CardRuntimeStatus::Applying, std::memory_order_release);
    return true;
}

