const char* WetMaterialTransitionStatus() {
    static thread_local char status[192]{};
    if (!WetMaterialTransitionAvailable())
        return "Unavailable (retail Swap/Restore signatures did not resolve)";
    if (!g_wetMaterialTransitionEnabled.load(std::memory_order_relaxed))
        return "Ready (disabled)";
    const int phase = g_wetVisualPhaseStatus.load(std::memory_order_relaxed);
    const char* phaseName = phase == static_cast<int>(WetVisualPhase::Preparing) ? "Preparing" :
                            phase == static_cast<int>(WetVisualPhase::Wetting) ? "Wetting" :
                            phase == static_cast<int>(WetVisualPhase::Wet) ? "Wet" :
                            phase == static_cast<int>(WetVisualPhase::Drying) ? "Drying" : "Idle";
    std::snprintf(status, sizeof(status),
                  "Active | %s %.0f%%",
                  phaseName, g_wetVisualBlend.load(std::memory_order_relaxed) * 100.0f);
    return status;
}

