bool FlyModeAvailable() {
    return g_instanceToolsAvailable && g_gameplayDispatchAvailable && g_instanceSetPosition != nullptr &&
           g_flyTraversalSuppressionAvailable && g_originalPlayerPhysicsProcess != nullptr;
}

bool FlyModeEnabled() {
    return g_flyMode.load(std::memory_order_relaxed);
}

bool SetFlyMode(bool value) {
    if (value && !FlyModeAvailable()) return false;
    const bool previous = g_flyMode.exchange(value, std::memory_order_acq_rel);
    if (previous != value) {
        if (value) {
            g_flyIdentityFramesUntilCheck = kFlyIdentityCheckFrames;
            g_flyPositionInitialized = false;
            ResetFlyRuntimeCache();

            const bool deathActive = g_deathCameraFollowActive.load(std::memory_order_acquire);
            if (deathActive)
                g_flySuspendedForF11Death.store(true, std::memory_order_release);
            const bool suspended = deathActive || g_flySuspendedForF11Death.load(std::memory_order_acquire);

            if (!suspended) {
                
                
                void* player = CurrentPlayer();
                void* instance = CurrentPlayerInstance();
                if (player && instance) {
                    RefreshFlyRuntimeCache(player, instance, true);
                    NeutralizeCachedPlayerFlightState(player, instance);
                    ClearCachedFlyMarkupTargets();
                }
                g_flyPhysicsHoldActive.store(true, std::memory_order_release);
                Log::Detailf("Player: Fly mode enabled (transform controls + zero-delta PlayerPhysics hold; player=%p instance=%p physics=%p runtime=%p markup=%p)",
                            g_flyCachedPlayer.load(std::memory_order_relaxed),
                            g_flyCachedInstance.load(std::memory_order_relaxed),
                            g_flyCachedPlayerPhysics.load(std::memory_order_relaxed),
                            g_flyCachedPhysicsRuntime.load(std::memory_order_relaxed),
                            g_flyCachedMarkupComponent.load(std::memory_order_relaxed));
            } else {
                
                
                
                
                g_flyPhysicsHoldActive.store(false, std::memory_order_release);
                Log::Detail("Player: Fly mode enabled but temporarily suspended until F11 death/reload completes");
            }
        } else {
            
            
            
            g_flyPhysicsHoldActive.store(false, std::memory_order_release);
            if (!g_deathCameraFollowActive.load(std::memory_order_acquire))
                NeutralizePlayerFlightState();
            g_flySuspendedForF11Death.store(false, std::memory_order_release);
            g_flyPositionInitialized = false;
            Log::Detail("Player: Fly mode disabled (native physics restored immediately; no post-disable velocity clamp)");
        }
    }
    return true;
}

const char* FlyModeStatus() {
    if (!FlyModeAvailable()) return "Unavailable";
    if (!FlyModeEnabled()) return "Ready - press F2 to enable";
    if (g_deathCameraFollowActive.load(std::memory_order_acquire) ||
        g_flySuspendedForF11Death.load(std::memory_order_acquire))
        return "Enabled - temporarily suspended during F11 death/reload";
    return "Active - WASD move, Q up, Z down, F2 disables";
}

