int OutfitCount() {
    if (!g_outfitControlsAvailable) return 0;
    unsigned int rawCount = 0;
    const std::uint8_t* list = nullptr;
    if (!GetOutfitTable(rawCount, list) || !CharacterProfileTableReady()) return 0;

    int available = 0;
    for (unsigned int i = 0; i < rawCount; ++i) {
        const auto* outfit = list + static_cast<std::size_t>(i) * kOutfitDataStride;
        const std::uint16_t objectId = *reinterpret_cast<const std::uint16_t*>(
            outfit + kOutfitPlayerObjectOffset);
        int profileIndex = -1;
        const char* objectName = nullptr;
        if (ResolveCharacterProfile(objectId, profileIndex, objectName))
            ++available;
    }
    return available;
}

bool GetOutfitInfo(int availableIndex, OutfitInfo& out) {
    out = {};
    if (!g_outfitControlsAvailable || availableIndex < 0) return false;

    unsigned int rawCount = 0;
    const std::uint8_t* list = nullptr;
    if (!GetOutfitTable(rawCount, list) || !CharacterProfileTableReady()) return false;

    int currentAvailable = 0;
    for (unsigned int rawIndex = 0; rawIndex < rawCount; ++rawIndex) {
        const auto* outfit = list + static_cast<std::size_t>(rawIndex) * kOutfitDataStride;
        const std::uint16_t objectId = *reinterpret_cast<const std::uint16_t*>(
            outfit + kOutfitPlayerObjectOffset);
        int profileIndex = -1;
        const char* objectName = nullptr;
        if (!ResolveCharacterProfile(objectId, profileIndex, objectName)) continue;
        if (currentAvailable++ != availableIndex) continue;

        out.outfitIndex = rawIndex;
        out.playerObjectId = objectId;
        out.characterProfileIndex = profileIndex;
        if (objectName && objectName[0])
            strncpy_s(out.objectName, objectName, _TRUNCATE);
        else
            std::snprintf(out.objectName, sizeof(out.objectName), "object_%u", static_cast<unsigned int>(objectId));
        return true;
    }
    return false;
}

const void* OutfitData(int availableIndex) {
    OutfitInfo info{};
    if (!GetOutfitInfo(availableIndex, info)) return nullptr;
    unsigned int rawCount = 0;
    const std::uint8_t* list = nullptr;
    if (!GetOutfitTable(rawCount, list) || info.outfitIndex >= rawCount) return nullptr;
    return list + static_cast<std::size_t>(info.outfitIndex) * kOutfitDataStride;
}

std::uint16_t CurrentOutfitObjectId() {
    if (!g_outfitControlsAvailable || !g_getLocalNetPlayerInfo || !g_getCharacterProfileObjectId) return 0;
    
    
    if (!CurrentPlayerInstance()) return 0;
    void* playerInfo = g_getLocalNetPlayerInfo(0);
    if (!playerInfo) return 0;
    return static_cast<std::uint16_t>(g_getCharacterProfileObjectId(playerInfo));
}

// (v0.9.455) Back in the main menu: the outfit pinned by the last swap (kept loaded for good, so a level load finds it
// loaded already and nothing of it is read again) let go when the text or voice language changed since it was loaded:
// its sound banks (Lara's grunts) are in the old language; the next level loads the worn outfit afresh, in the new one.
void ReleaseOutfitPinIfLanguageChanged() {
    const unsigned int pinned = g_pinnedOutfitObjectId.load(std::memory_order_relaxed);
    if (!pinned || OutfitSwapInProgress()) return;
    const int text = SoundReplace::TextLanguage(), voice = SoundReplace::VoiceLanguage();
    const int pinnedText = g_pinnedTextLanguage.load(std::memory_order_relaxed);
    const int pinnedVoice = g_pinnedVoiceLanguage.load(std::memory_order_relaxed);
    if (text == pinnedText && voice == pinnedVoice) return;
    ReleaseTrainerOutfitPreload(pinned);
    g_pinnedOutfitObjectId.store(0, std::memory_order_relaxed);
    Log::Writef("Outfits: the language changed (text %s -> %s, voice %s -> %s): the outfit kept loaded since its swap "
                "(object %u) is let go, to load again in the new language", SoundReplace::LanguageName(pinnedText),
                SoundReplace::LanguageName(text), SoundReplace::LanguageName(pinnedVoice), SoundReplace::LanguageName(voice),
                pinned);
}

bool OutfitSwapInProgress() {
    const auto state = g_outfitSwapState.load(std::memory_order_relaxed);
    return state == OutfitSwapState::Requested || state == OutfitSwapState::Loading ||
           state == OutfitSwapState::Loaded || state == OutfitSwapState::Respawning;
}

const char* OutfitSwapStatus() {
    switch (g_outfitSwapState.load(std::memory_order_relaxed)) {
        case OutfitSwapState::Unavailable: return "Unavailable";
        case OutfitSwapState::Ready: return "Ready";
        case OutfitSwapState::Requested: return "Outfit selected; waiting for game thread...";
        case OutfitSwapState::Loading: return "Loading selected outfit object...";
        case OutfitSwapState::Loaded: return "Outfit loaded; waiting to respawn player...";
        case OutfitSwapState::Respawning: return "Applying outfit / waiting for replacement player instance...";
        case OutfitSwapState::Failed: return "Last outfit swap failed or timed out";
    }
    return "Unknown";
}

// v0.9.342 (the cutscene viewer): the outfit's name as the game shows it (its string ID at +0 through localstr_get, which
// CustomOutfits answers for its own outfits), and the local player's character profile the next spawn uses
// (NetPlayerInfo +0x6019; NetPlayerInfo::SetCharacterProfileIndex, retail 0x58F3B0, as TR2 0x5C3EC0).
constexpr std::uintptr_t kRvaLocalstrGetForOutfits = 0x000832D0ull;
constexpr std::uint8_t kLocalstrGetForOutfitsSig[] = {0x48, 0x85, 0xD2, 0x74, 0x03, 0xC6, 0x02, 0x01, 0x83, 0xF9, 0xFF, 0x75};
constexpr std::uintptr_t kRvaSetCharacterProfileIndex = 0x0058F3B0ull;
constexpr std::uint8_t kSetCharacterProfileIndexSig[] = {0x48, 0x89, 0x5C, 0x24, 0x08, 0x48, 0x89, 0x74, 0x24, 0x10, 0x57,
                                                         0x48, 0x83, 0xEC, 0x20, 0x48, 0x8B, 0x01, 0x41, 0x0F, 0xB6, 0xF0};
constexpr std::ptrdiff_t kNetPlayerInfoProfileIndexOffset = 0x6019;

bool OutfitDisplayName(int availableIndex, char* out, std::size_t capacity) {
    if (!out || !capacity) return false;
    out[0] = 0;
    OutfitInfo info;
    if (!GetOutfitInfo(availableIndex, info)) return false;
    unsigned int rawCount = 0;
    const std::uint8_t* list = nullptr;
    if (!GetOutfitTable(rawCount, list) || info.outfitIndex >= rawCount) return false;
    // (CustomOutfits hooks localstr_get: its first bytes are then MinHook's jump)
    static const bool verified = GameBuild::VerifyBytes(kRvaLocalstrGetForOutfits, kLocalstrGetForOutfitsSig,
                                                        sizeof(kLocalstrGetForOutfitsSig)) ||
                                 *reinterpret_cast<const std::uint8_t*>(GameBuild::Base() + kRvaLocalstrGetForOutfits) == 0xE9;
    const std::uint16_t nameId =
        *reinterpret_cast<const std::uint16_t*>(list + static_cast<std::size_t>(info.outfitIndex) * kOutfitDataStride);
    const char* name = nullptr;
    if (verified && nameId != 0xFFFF) {
        bool found = false;
        name = reinterpret_cast<const char*(__fastcall*)(int, bool*)>(GameBuild::Base() + kRvaLocalstrGetForOutfits)(nameId, &found);
        if (!found) name = nullptr;
    }
    strncpy_s(out, capacity, name && name[0] ? name : info.objectName, _TRUNCATE);
    return true;
}

void* LocalNetPlayerInfo() { return g_getLocalNetPlayerInfo ? g_getLocalNetPlayerInfo(0) : nullptr; }

// Instances of the named objects hidden (drawing only), as InstanceUtils::SetCapabilities hides one (retail 0x3EC6D0,
// TR2 0x416C50: the DrawableComponent, component 8 at Instance +0xD8 when +0xD0 > 8; its +0xC8 bit 0 set after
// DrawableComponent::InvalidateFlags (retail 0x3E3930), then DrawableComponent::HideStaticMeshes (retail 0x3DFAD0)).
// For the Cutscene Viewer: a gameplay copy of a prop that the story hides before its cutscene (cutscenes.json "hide").
namespace {
constexpr std::uintptr_t kRvaDrawableInvalidateFlags = 0x003E3930ull, kRvaDrawableHideStaticMeshes = 0x003DFAD0ull,
                         kRvaSetCapabilities = 0x003EC6D0ull;
constexpr std::uint8_t kSetCapabilitiesSig[] = {0x48, 0x89, 0x5C, 0x24, 0x10, 0x48, 0x89, 0x6C, 0x24, 0x18, 0x56, 0x48,
                                                0x83, 0xEC, 0x20, 0x48, 0x89, 0x7C, 0x24, 0x30, 0x48, 0x8B, 0xEA, 0x33};
int g_hideFnsState = 0;   // 0 unchecked, 1 ready, -1 not where expected

// 1 hidden now, 0 already hidden or nothing to hide, -1 fault
int HideInstanceDrawing(std::uint8_t* instance) noexcept {
    __try {
        if (*reinterpret_cast<std::uint32_t*>(instance + 0xD0) <= 8) return 0;
        auto* drawable = (*reinterpret_cast<std::uint8_t***>(instance + 0xD8))[8];
        if (!drawable || (drawable[0xC8] & 1)) return 0;
        const std::uintptr_t base = GameBuild::Base();
        reinterpret_cast<void(__fastcall*)(void*)>(base + kRvaDrawableInvalidateFlags)(drawable);
        drawable[0xC8] = std::uint8_t(drawable[0xC8] | 1);
        reinterpret_cast<void(__fastcall*)(void*)>(base + kRvaDrawableHideStaticMeshes)(drawable);
        return 1;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return -1;
    }
}
}  // namespace

namespace {
bool ReadInstanceSpot(std::uint8_t* instance, float at[3], bool& hidden) noexcept {
    __try {
        std::memcpy(at, instance + kInstanceRespawnPositionOffset, sizeof(float) * 3);
        hidden = false;
        if (*reinterpret_cast<std::uint32_t*>(instance + 0xD0) > 8)
            if (auto* drawable = (*reinterpret_cast<std::uint8_t***>(instance + 0xD8))[8]) hidden = (drawable[0xC8] & 1) != 0;
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}
}  // namespace

// The object an instance is of, by its name in the object list ("?" when not known; "(none)" for no instance).
std::string InstanceObjectName(void* instance) {
    if (!instance) return "(none)";
    EnsureZoneListLoaded();
    std::uint32_t zone = 0;
    if (!TryGetInstanceObjectZoneId(instance, zone)) return "?";
    if (zone < g_zoneNameById.size() && !g_zoneNameById[zone].empty()) return g_zoneNameById[zone];
    return "zone " + std::to_string(zone);
}

// The live instances within `radius` of Lara, nearest first: "name (zone, distance m[, hidden])".
std::string DescribeInstancesNearPlayer(float radius, int maxCount) {
    EnsureZoneListLoaded();
    void* player = CurrentPlayerInstance();
    if (!player) return "(no player)";
    float origin[3];
    std::memcpy(origin, static_cast<std::uint8_t*>(player) + kInstanceRespawnPositionOffset, sizeof(origin));
    struct Near {
        float distance;
        std::uint32_t zone, slot;
        bool hidden;
    };
    std::vector<Near> nearby;
    auto* pool = reinterpret_cast<std::uint8_t*>(GameBuild::Base() + kRvaInstancePool);
    for (std::uint32_t slot = 1; slot < kMaxInstanceSlots; ++slot) {
        auto* candidate = pool + static_cast<std::size_t>(slot) * kInstanceStride;
        const std::uint64_t fullId = *reinterpret_cast<const std::uint64_t*>(candidate + kInstanceSlotIdOffset);
        if (!fullId || static_cast<std::uint32_t>(fullId) != slot || candidate == player) continue;
        float at[3];
        bool hidden = false;
        if (!ReadInstanceSpot(candidate, at, hidden)) continue;
        const float dx = at[0] - origin[0], dy = at[1] - origin[1], dz = at[2] - origin[2];
        const float distance = std::sqrt(dx * dx + dy * dy + dz * dz);
        if (!(distance <= radius)) continue;
        std::uint32_t zone = 0;
        TryGetInstanceObjectZoneId(candidate, zone);
        nearby.push_back({distance, zone, slot, hidden});
    }
    std::sort(nearby.begin(), nearby.end(), [](const Near& a, const Near& b) { return a.distance < b.distance; });
    std::string text;
    char line[160];
    int shown = 0;
    for (const Near& n : nearby) {
        if (shown++ >= maxCount) break;
        const char* name = n.zone < g_zoneNameById.size() && !g_zoneNameById[n.zone].empty() ? g_zoneNameById[n.zone].c_str() : "?";
        snprintf(line, sizeof(line), "%s%s (zone %u, %.1f m%s)", text.empty() ? "" : "; ", name, n.zone, n.distance,
                 n.hidden ? ", hidden" : "");
        text += line;
    }
    if (int(nearby.size()) > maxCount) text += "; ... " + std::to_string(nearby.size() - maxCount) + " more";
    return text.empty() ? "(none)" : text;
}

int CopyInstanceSpots(std::vector<InstanceSpot>& out) {
    out.clear();
    if (!GameBuild::Base()) return 0;
    auto* pool = reinterpret_cast<std::uint8_t*>(GameBuild::Base() + kRvaInstancePool);
    for (std::uint32_t slot = 1; slot < kMaxInstanceSlots; ++slot) {
        auto* candidate = pool + static_cast<std::size_t>(slot) * kInstanceStride;
        const std::uint64_t fullId = *reinterpret_cast<const std::uint64_t*>(candidate + kInstanceSlotIdOffset);
        if (!fullId || static_cast<std::uint32_t>(fullId) != slot) continue;
        InstanceSpot spot;
        bool hidden = false;
        if (!ReadInstanceSpot(candidate, spot.at, hidden)) continue;
        spot.id = fullId;
        TryGetInstanceObjectZoneId(candidate, spot.zone);
        out.push_back(spot);
    }
    return int(out.size());
}

bool PlayerPosition(float at[3]) {
    void* player = CurrentPlayerInstance();
    if (!player) return false;
    std::memcpy(at, static_cast<std::uint8_t*>(player) + kInstanceRespawnPositionOffset, sizeof(float) * 3);
    return true;
}

std::string ObjectNameOfZone(std::uint32_t zone) {
    EnsureZoneListLoaded();
    if (zone < g_zoneNameById.size() && !g_zoneNameById[zone].empty()) return g_zoneNameById[zone];
    return zone ? "zone " + std::to_string(zone) : std::string("?");
}

bool HideFnsReady() {
    if (g_hideFnsState == 0) {
        // (the drawable calls are checked through SetCapabilities' own calls to them)
        const std::uintptr_t base = GameBuild::Base();
        auto callTarget = [&](std::uintptr_t at) {
            return at + 5 + static_cast<std::intptr_t>(*reinterpret_cast<const std::int32_t*>(base + at + 1));
        };
        g_hideFnsState = Verify(kRvaSetCapabilities, kSetCapabilitiesSig, sizeof(kSetCapabilitiesSig), "InstanceUtils::SetCapabilities") &&
                                 *reinterpret_cast<const std::uint8_t*>(base + 0x3EC742) == 0xE8 &&
                                 *reinterpret_cast<const std::uint8_t*>(base + 0x3EC751) == 0xE8 &&
                                 callTarget(0x3EC742) == kRvaDrawableInvalidateFlags &&
                                 callTarget(0x3EC751) == kRvaDrawableHideStaticMeshes
                             ? 1
                             : -1;
    }
    return g_hideFnsState > 0;
}

int HideInstance(void* instance) {
    if (!instance || !HideFnsReady()) return -1;
    return HideInstanceDrawing(static_cast<std::uint8_t*>(instance));
}

int HideInstancesOfObjects(const std::vector<std::string>& objectNames, int* found) {
    if (found) *found = 0;
    if (objectNames.empty() || !HideFnsReady()) return 0;
    EnsureZoneListLoaded();
    if (!g_zoneListLoaded) return 0;
    std::vector<std::uint32_t> ids;
    for (std::uint32_t id = 0; id < g_zoneNameById.size(); ++id) {
        if (g_zoneNameById[id].empty()) continue;
        for (const std::string& name : objectNames)
            if (_stricmp(g_zoneNameById[id].c_str(), name.c_str()) == 0) {
                ids.push_back(id);
                break;
            }
    }
    if (ids.empty()) {
        if (found) *found = -1;   // (none of the names is an object)
        return 0;
    }
    auto* pool = reinterpret_cast<std::uint8_t*>(GameBuild::Base() + kRvaInstancePool);
    int hidden = 0, count = 0;
    for (std::uint32_t slot = 1; slot < kMaxInstanceSlots; ++slot) {
        auto* candidate = pool + static_cast<std::size_t>(slot) * kInstanceStride;
        const std::uint64_t fullId = *reinterpret_cast<const std::uint64_t*>(candidate + kInstanceSlotIdOffset);
        if (!fullId || static_cast<std::uint32_t>(fullId) != slot) continue;
        std::uint32_t zoneId = 0;
        if (!TryGetInstanceObjectZoneId(candidate, zoneId)) continue;
        if (std::find(ids.begin(), ids.end(), zoneId) == ids.end()) continue;
        ++count;
        if (HideInstanceDrawing(candidate) > 0) ++hidden;
    }
    if (found) *found = count;
    return hidden;
}

// The live instances of these objects removed (the game's Instance::EnableRemoveThisFrame(instance, false), as the
// instance tools' delete): the count asked to go; found: those live (-1: none of the names is an object).
int RemoveInstancesOfObjects(const std::vector<std::string>& objectNames, int* found) {
    if (found) *found = 0;
    if (objectNames.empty()) return 0;
    EnsureZoneListLoaded();
    if (!g_zoneListLoaded) return 0;
    std::vector<std::uint32_t> ids;
    for (std::uint32_t id = 0; id < g_zoneNameById.size(); ++id) {
        if (g_zoneNameById[id].empty()) continue;
        for (const std::string& name : objectNames)
            if (_stricmp(g_zoneNameById[id].c_str(), name.c_str()) == 0) {
                ids.push_back(id);
                break;
            }
    }
    if (ids.empty()) {
        if (found) *found = -1;
        return 0;
    }
    auto* pool = reinterpret_cast<std::uint8_t*>(GameBuild::Base() + kRvaInstancePool);
    int removed = 0, count = 0;
    for (std::uint32_t slot = 1; slot < kMaxInstanceSlots; ++slot) {
        auto* candidate = pool + static_cast<std::size_t>(slot) * kInstanceStride;
        const std::uint64_t fullId = *reinterpret_cast<const std::uint64_t*>(candidate + kInstanceSlotIdOffset);
        if (!fullId || static_cast<std::uint32_t>(fullId) != slot) continue;
        std::uint32_t zoneId = 0;
        if (!TryGetInstanceObjectZoneId(candidate, zoneId)) continue;
        if (std::find(ids.begin(), ids.end(), zoneId) == ids.end()) continue;
        ++count;
        if (g_instanceEnableRemoveThisFrame) {
            g_instanceEnableRemoveThisFrame(candidate, false);
            ++removed;
        }
    }
    if (found) *found = count;
    return removed;
}

int LocalPlayerCharacterProfile() {
    void* playerInfo = g_getLocalNetPlayerInfo ? g_getLocalNetPlayerInfo(0) : nullptr;
    if (!playerInfo || !IsReadableRange(static_cast<std::uint8_t*>(playerInfo) + kNetPlayerInfoProfileIndexOffset, 1))
        return -1;
    return static_cast<std::int8_t>(static_cast<std::uint8_t*>(playerInfo)[kNetPlayerInfoProfileIndexOffset]);
}

bool SetLocalPlayerCharacterProfile(int profileIndex) {
    // (the Cutscene Viewer hooks it: its first bytes are then MinHook's jump)
    static const bool verified = GameBuild::VerifyBytes(kRvaSetCharacterProfileIndex, kSetCharacterProfileIndexSig,
                                                        sizeof(kSetCharacterProfileIndexSig)) ||
                                 *reinterpret_cast<const std::uint8_t*>(GameBuild::Base() + kRvaSetCharacterProfileIndex) == 0xE9;
    void* playerInfo = g_getLocalNetPlayerInfo ? g_getLocalNetPlayerInfo(0) : nullptr;
    if (!verified || !playerInfo || profileIndex < 0 || profileIndex > 127) return false;
    reinterpret_cast<void(__fastcall*)(void*, char, bool)>(GameBuild::Base() + kRvaSetCharacterProfileIndex)(
        playerInfo, static_cast<char>(profileIndex), true);
    return LocalPlayerCharacterProfile() == profileIndex;
}

bool RequestOutfitSwap(unsigned int outfitIndex) {
    if (!g_outfitControlsAvailable || !g_objectZoneLoadAndAddRef2 || OutfitSwapInProgress())
        return false;
    // (v0.9.440: the respawn would end the cutscene; the flag a tick old confirmed now: the Cutscene Viewer asks right
    // after one ended, before its own starts)
    if (g_cutscenePlaying.load(std::memory_order_acquire) && Cutscenes::AnyCutscenePlaying()) {
        Log::Write("Outfits: switching outfit refused: a cutscene plays (it plays on the player instance a switch replaces)");
        return false;
    }

    std::uint16_t objectId = 0;
    int profileIndex = -1;
    const char* objectName = nullptr;
    if (!GetRawOutfit(outfitIndex, objectId, profileIndex, objectName) || objectId == 0)
        return false;

    const std::uint16_t currentObjectId = CurrentOutfitObjectId();
    if (currentObjectId != 0 && currentObjectId == objectId) {
        g_outfitSwapState.store(OutfitSwapState::Ready, std::memory_order_relaxed);
        return true;
    }

    const bool f11DeathCameraActive =
        g_deathCameraFollowActive.load(std::memory_order_acquire);
    if (f11DeathCameraActive) {
        g_outfitCameraResetAfterF11.store(true, std::memory_order_release);
        g_outfitCameraResetPreApplied.store(false, std::memory_order_release);
        Log::Detail("Camera: outfit switch requested during F11 death; native camera reset armed");
        CrashDiagnostics::SetBreadcrumb("Outfit requested during F11 death; camera reset armed");
    } else {
        
        
        g_outfitCameraResetAfterF11.store(false, std::memory_order_release);
        g_outfitCameraResetPreApplied.store(false, std::memory_order_release);
    }

    g_requestedOutfitIndex.store(outfitIndex, std::memory_order_relaxed);
    g_requestedOutfitObjectId.store(objectId, std::memory_order_relaxed);
    g_requestedCharacterProfile.store(profileIndex, std::memory_order_relaxed);
    g_lastOutfitLoadCallbackValue.store(0, std::memory_order_relaxed);
    g_requestedUsesExistingPinnedRef.store(false, std::memory_order_relaxed);
    g_outfitLoggedInteractionWait = false;
    g_outfitLoggedPauseWait = false;
    g_outfitLoggedCutsceneWait = false;
    g_outfitSwapState.store(OutfitSwapState::Requested, std::memory_order_release);

    Log::Detailf("Outfits: queued object %u (%s), outfit index %u, profile %d",
                static_cast<unsigned int>(objectId), objectName ? objectName : "unnamed",
                outfitIndex, profileIndex);
    return true;
}

bool RequestNextOutfit() {
    if (!g_outfitControlsAvailable || OutfitSwapInProgress() || g_cutscenePlaying.load(std::memory_order_acquire))
        return false;

    const std::uint16_t currentObjectId = CurrentOutfitObjectId();
    if (currentObjectId == 0)
        return false;

    unsigned int rawCount = 0;
    const std::uint8_t* list = nullptr;
    if (!GetOutfitTable(rawCount, list) || rawCount == 0 || !CharacterProfileTableReady())
        return false;
    (void)list;

    
    
    
    unsigned int currentRaw = std::numeric_limits<unsigned int>::max();
    const unsigned int requestedRaw = g_requestedOutfitIndex.load(std::memory_order_relaxed);
    if (requestedRaw < rawCount) {
        std::uint16_t requestedObjectId = 0;
        int profileIndex = -1;
        const char* objectName = nullptr;
        if (GetRawOutfit(requestedRaw, requestedObjectId, profileIndex, objectName) &&
            requestedObjectId == currentObjectId) {
            currentRaw = requestedRaw;
        }
    }

    if (currentRaw == std::numeric_limits<unsigned int>::max()) {
        for (unsigned int raw = 0; raw < rawCount; ++raw) {
            std::uint16_t objectId = 0;
            int profileIndex = -1;
            const char* objectName = nullptr;
            if (GetRawOutfit(raw, objectId, profileIndex, objectName) && objectId == currentObjectId) {
                currentRaw = raw;
                break;
            }
        }
    }

    
    
    const unsigned int startRaw =
        currentRaw == std::numeric_limits<unsigned int>::max() ? 0u : (currentRaw + 1u) % rawCount;
    for (unsigned int step = 0; step < rawCount; ++step) {
        const unsigned int raw = (startRaw + step) % rawCount;
        std::uint16_t objectId = 0;
        int profileIndex = -1;
        const char* objectName = nullptr;
        if (!GetRawOutfit(raw, objectId, profileIndex, objectName) || objectId == 0)
            continue;
        if (raw == currentRaw || objectId == currentObjectId)
            continue;
        return RequestOutfitSwap(raw);
    }
    return false;
}

