void SetClothLevelCollisionEnabled(bool enabled) {
    if (!ClothLevelCollisionAvailable()) enabled = false;
    g_clothLevelCollisionEnabled.store(enabled, std::memory_order_release);
    
    
    
    
    if (!enabled) {
        if (g_clothLevelDiagnosticsEnabled.exchange(false, std::memory_order_acq_rel))
            Log::Detail("ClothLevelDiag disabled because Cloth level collision was disabled");
        g_clothLevelTargetStateCount.store(0, std::memory_order_release);
        g_clothLevelPublishedScene.store(0, std::memory_order_release);
        g_clothLevelPublishedPlayer.store(0, std::memory_order_release);
        ClearClothLevelSupportCache();
    }
    Settings::Get().clothLevelCollision = enabled;
}

bool ClothLevelCollisionDiagnosticsEnabled() {
    return ClothLevelCollisionEnabled() &&
           g_clothLevelDiagnosticsEnabled.load(std::memory_order_relaxed);
}

void SetClothLevelCollisionDiagnosticsEnabled(bool enabled) {
    if (!ClothLevelCollisionEnabled()) enabled = false;
    const bool previous = g_clothLevelDiagnosticsEnabled.load(std::memory_order_acquire);
    if (enabled) {
        if (!previous) {
            ResetClothLevelDiagnostics();
            g_clothLevelDiagnosticsManifestPending.store(true, std::memory_order_release);
            g_clothLevelDiagnosticsEnabled.store(true, std::memory_order_release);
            Log::Detail(
                "ClothLevelDiag enabled: throttled per-ClothState collision diagnostics will be written once per second");
        }
    } else if (previous) {
        g_clothLevelDiagnosticsEnabled.store(false, std::memory_order_release);
        Log::Detail("ClothLevelDiag disabled");
    }
}

