void SetClothEditorTarget(std::uint32_t instanceId, std::uint64_t expectedComponentId) {
    if (!g_clothControlsAvailable) return;
    const auto oldId = g_clothTargetInstanceId.exchange(instanceId, std::memory_order_acq_rel);
    const auto oldComponent = g_clothTargetComponentId.exchange(expectedComponentId, std::memory_order_acq_rel);
    if (oldId != instanceId || oldComponent != expectedComponentId) {
        {
            std::lock_guard<std::mutex> lock(g_clothMutex);
            g_clothSnapshot = {};
            g_pendingClothEdit = {};
        }
        g_hasPendingClothEdit.store(false, std::memory_order_release);
        g_forceClothSnapshot.store(true, std::memory_order_release);
    }
}

