bool QueueClothStripGroupUpdate(int listIndex, const ClothStripGroupSettings& settings) {
    if (!g_clothControlsAvailable || listIndex < 0 || !ClothSettingsAreSane(settings)) return false;
    std::lock_guard<std::mutex> lock(g_clothMutex);
    if (listIndex >= g_clothSnapshot.groupCount || !g_clothSnapshot.targetInstance ||
        !g_clothSnapshot.component || !g_clothSnapshot.tune)
        return false;

    const auto& group = g_clothSnapshot.groups[static_cast<std::size_t>(listIndex)];
    g_pendingClothEdit.pending = true;
    g_pendingClothEdit.expectedTargetInstance = g_clothSnapshot.targetInstance;
    g_pendingClothEdit.expectedInstanceId = g_clothSnapshot.targetInstanceId;
    g_pendingClothEdit.expectedInstanceComponentId = g_clothSnapshot.targetComponentId;
    g_pendingClothEdit.expectedComponent = g_clothSnapshot.component;
    g_pendingClothEdit.expectedTune = g_clothSnapshot.tune;
    g_pendingClothEdit.expectedConfig = g_clothSnapshot.runtime.currentConfigIndex;
    g_pendingClothEdit.activeIndex = group.activeIndex;
    g_pendingClothEdit.groupIndex = group.groupIndex;
    g_pendingClothEdit.settings = settings;
    g_pendingClothEdit.originalSettings = group.originalSettings;
    g_pendingClothEdit.hasOriginalSettings = group.hasOriginalSettings;
    g_hasPendingClothEdit.store(true, std::memory_order_release);
    g_clothStatusState.store(ClothStatusState::UpdateQueued, std::memory_order_release);
    return true;
}

bool RestoreClothStripGroupOriginal(int listIndex, ClothStripGroupSettings* restored) {
    if (!g_clothControlsAvailable || listIndex < 0) return false;

    ClothStripGroupSettings original{};
    {
        std::lock_guard<std::mutex> lock(g_clothMutex);
        if (listIndex >= g_clothSnapshot.groupCount || !g_clothSnapshot.targetInstance ||
            !g_clothSnapshot.component || !g_clothSnapshot.tune)
            return false;
        const auto& group = g_clothSnapshot.groups[static_cast<std::size_t>(listIndex)];
        if (!group.hasOriginalSettings) return false;
        original = group.originalSettings;

        g_pendingClothEdit.pending = true;
        g_pendingClothEdit.expectedTargetInstance = g_clothSnapshot.targetInstance;
        g_pendingClothEdit.expectedInstanceId = g_clothSnapshot.targetInstanceId;
        g_pendingClothEdit.expectedInstanceComponentId = g_clothSnapshot.targetComponentId;
        g_pendingClothEdit.expectedComponent = g_clothSnapshot.component;
        g_pendingClothEdit.expectedTune = g_clothSnapshot.tune;
        g_pendingClothEdit.expectedConfig = g_clothSnapshot.runtime.currentConfigIndex;
        g_pendingClothEdit.activeIndex = group.activeIndex;
        g_pendingClothEdit.groupIndex = group.groupIndex;
        g_pendingClothEdit.settings = original;
        g_pendingClothEdit.originalSettings = group.originalSettings;
        g_pendingClothEdit.hasOriginalSettings = group.hasOriginalSettings;
        g_hasPendingClothEdit.store(true, std::memory_order_release);
        g_clothStatusState.store(ClothStatusState::UpdateQueued, std::memory_order_release);
    }
    if (restored) *restored = original;
    return true;
}


