// (v0.9.586) the locked motion profile
bool HairProfileLockAvailable() { return g_hairControlsAvailable; }
std::string HairLockedMotionProfile() {
    std::lock_guard<std::mutex> lock(g_hairLockMutex);
    return g_hairLockName;
}
void SetHairLockedMotionProfile(const char* name) {
    const std::string wanted = name ? name : "";
    {
        std::lock_guard<std::mutex> lock(g_hairLockMutex);
        if (wanted == g_hairLockName) return;
        g_hairLockName = wanted;
    }
    strncpy_s(Settings::Get().hairLockedMotionProfile, wanted.c_str(), _TRUNCATE);
    g_hairLockGameAsked.store(kInvalidHairProfile, std::memory_order_relaxed);
    g_hairLockMissingSaid = 0;
    // the index at once from the editor's snapshot (a profile picked in the menu is not taken back meanwhile)
    unsigned int index = kInvalidHairProfile;
    std::uintptr_t component = 0;
    if (!wanted.empty()) {
        std::lock_guard<std::mutex> lock(g_hairMutex);
        for (int i = 0; i < g_hairSnapshot.simProfileCount && i < kMaxHairProfiles; ++i) {
            if (_stricmp(g_hairSnapshot.simProfiles[static_cast<std::size_t>(i)].name, wanted.c_str()) == 0) {
                index = static_cast<unsigned int>(i);
                component = g_hairSnapshot.component;
                break;
            }
        }
    }
    g_hairLockIndex.store(index, std::memory_order_release);
    g_hairLockComponent.store(index == kInvalidHairProfile ? 0 : component, std::memory_order_release);
    g_hairLockSet.store(!wanted.empty(), std::memory_order_release);
    g_hairLockRecheck.store(true, std::memory_order_release);
    if (wanted.empty())
        Log::Write("Hair: the motion profile is the game's to choose again");
    else
        Log::Writef("Hair: the motion profile locked to \"%s\"", wanted.c_str());
}
bool HairLockedProfileMissing() {
    return g_hairLockSet.load(std::memory_order_relaxed) && g_hairLockMissing.load(std::memory_order_relaxed);
}
int HairLockLastGameRequest() {
    const unsigned int asked = g_hairLockGameAsked.load(std::memory_order_relaxed);
    return asked == kInvalidHairProfile ? -1 : static_cast<int>(asked);
}

