bool QueueHairCommandInternal(PendingHairCommand cmd, HairStatusState state = HairStatusState::UpdateQueued) {
    if (!g_hairControlsAvailable || OutfitSwapInProgress()) return false;
    std::lock_guard<std::mutex> lock(g_hairMutex);
    if (!g_hairSnapshot.playerInstance || !g_hairSnapshot.component || !g_hairSnapshot.compData) return false;
    cmd.expectedPlayer = g_hairSnapshot.playerInstance;
    cmd.expectedComponent = g_hairSnapshot.component;
    cmd.expectedCompData = g_hairSnapshot.compData;
    g_pendingHairCommand = cmd; 
    g_hasPendingHairCommand.store(true, std::memory_order_release);
    g_hairStatusState.store(state, std::memory_order_release);
    return true;
}

bool QueueHairSimulationProfile(unsigned int profileIndex, float transitionSeconds) {
    if (!std::isfinite(transitionSeconds)) return false;
    {
        std::lock_guard<std::mutex> lock(g_hairMutex);
        if (profileIndex >= static_cast<unsigned int>(g_hairSnapshot.simProfileCount)) return false;
    }
    PendingHairCommand cmd{};
    cmd.type = HairCommandType::SimulationProfile;
    cmd.profileIndex = profileIndex;
    cmd.transitionSeconds = transitionSeconds;
    return QueueHairCommandInternal(cmd);
}

