        std::lock_guard<std::mutex> lock(g_hairMutex);
        if (index < 0 || index >= g_hairSnapshot.physicsGroupCount) return false;
        const auto& group = g_hairSnapshot.physicsGroups[static_cast<std::size_t>(index)];
        if (!group.hasOriginalSettings) return false;
