bool QueueHairRenderingProfileUpdate(int index, const HairRenderingProfileInfo& settings) {
    if (index < 0 || !std::isfinite(settings.dirtStrength)) return false;
    for (float c : settings.dirtColor) if (!std::isfinite(c)) return false;
    {
        std::lock_guard<std::mutex> lock(g_hairMutex);
        if (index >= g_hairSnapshot.renderProfileCount) return false;
    }
    PendingHairCommand cmd{};
    cmd.type = HairCommandType::RenderingSource;
    cmd.index = index;
    cmd.rendering = settings;
    return QueueHairCommandInternal(cmd);
}

bool QueueHairConstantGroupUpdate(int index, const HairConstantGroupInfo& settings, bool rebuild) {
    if (index < 0 || !HairConstantSettingsAreSane(settings)) return false;
    {
        std::lock_guard<std::mutex> lock(g_hairMutex);
        if (index >= g_hairSnapshot.constantGroupCount) return false;
    }
    PendingHairCommand cmd{};
    cmd.type = HairCommandType::ConstantGroup;
    cmd.index = index;
    cmd.constant = settings;
    cmd.resetSimulation = false;
    cmd.scheduleRebuild = rebuild;
    return QueueHairCommandInternal(cmd);
}

bool QueueHairAdvancedUpdate(const HairAdvancedSettings& settings, bool resetSimulation) {
    if (!HairAdvancedSettingsAreSane(settings)) return false;
    PendingHairCommand cmd{};
    cmd.type = HairCommandType::Advanced;
    cmd.advanced = settings;
    cmd.resetSimulation = resetSimulation;
    return QueueHairCommandInternal(cmd);
}

bool QueueHairResetSimulation() {
    PendingHairCommand cmd{};
    cmd.type = HairCommandType::ResetSimulation;
    return QueueHairCommandInternal(cmd);
}

bool QueueHairRebuild() {
    PendingHairCommand cmd{};
    cmd.type = HairCommandType::Rebuild;
    return QueueHairCommandInternal(cmd, HairStatusState::RebuildQueued);
}

