bool QueueCapsuleCollisionUpdate(unsigned int listIndex, std::uint32_t expectedItemId,
                                 const float matrix[16], float radius, float length, int segment) {
    if (!g_capsuleCollisionControlsAvailable || !matrix || !std::isfinite(radius) ||
        !std::isfinite(length) || segment < 0 || segment > 255) return false;
    for (int i = 0; i < 16; ++i) if (!std::isfinite(matrix[i])) return false;
    std::lock_guard<std::mutex> lock(g_capsuleCollisionMutex);
    bool found = false;
    for (const auto& info : g_capsuleCollisionSnapshot) {
        if (info.listIndex == listIndex && info.itemId == expectedItemId) { found = true; break; }
    }
    if (!found) return false;
    g_pendingCapsuleCollisionEdit.pending = true;
    g_pendingCapsuleCollisionEdit.instanceId = g_capsuleCollisionTargetInstanceId.load(std::memory_order_relaxed);
    g_pendingCapsuleCollisionEdit.componentId = g_capsuleCollisionTargetComponentId.load(std::memory_order_relaxed);
    g_pendingCapsuleCollisionEdit.listIndex = listIndex;
    g_pendingCapsuleCollisionEdit.expectedItemId = expectedItemId;
    std::memcpy(g_pendingCapsuleCollisionEdit.matrix, matrix, sizeof(g_pendingCapsuleCollisionEdit.matrix));
    g_pendingCapsuleCollisionEdit.radius = radius;
    g_pendingCapsuleCollisionEdit.length = length;
    g_pendingCapsuleCollisionEdit.segment = segment;
    g_hasPendingCapsuleCollisionEdit.store(true, std::memory_order_release);
    g_capsuleCollisionStatusState.store(CapsuleCollisionStatusState::UpdateQueued, std::memory_order_release);
    return true;
}

