bool QueueMarkerUpdate(unsigned int listIndex, std::uint32_t expectedItemId,
                       const float matrix[16], int boneSegment) {
    if (!g_markerControlsAvailable || !matrix) return false;
    for (int i = 0; i < 16; ++i) if (!std::isfinite(matrix[i])) return false;
    std::lock_guard<std::mutex> lock(g_markerMutex);
    if (listIndex >= g_markerSnapshot.size()) return false;
    const auto& current = g_markerSnapshot[listIndex];
    if (current.itemId != expectedItemId) return false;
    g_pendingMarkerEdit.pending = true; 
    g_pendingMarkerEdit.instanceId = g_markerTargetInstanceId.load(std::memory_order_relaxed);
    g_pendingMarkerEdit.componentId = g_markerTargetComponentId.load(std::memory_order_relaxed);
    g_pendingMarkerEdit.listIndex = listIndex;
    g_pendingMarkerEdit.expectedItemId = expectedItemId;
    std::memcpy(g_pendingMarkerEdit.matrix, matrix, sizeof(g_pendingMarkerEdit.matrix));
    g_pendingMarkerEdit.boneSegment = boneSegment;
    g_pendingMarkerEdit.boneCount = current.boneCount;
    g_pendingMarkerEdit.runtimeMarker =
        listIndex < g_markerRuntimePointers.size() ? g_markerRuntimePointers[listIndex] : 0;
    g_hasPendingMarkerEdit.store(true, std::memory_order_release);
    g_markerStatusState.store(MarkerStatusState::UpdateQueued, std::memory_order_release);
    return true;
}

bool PlayerMarkerOverrideAvailable() { return g_markerControlsAvailable; }

bool SetPlayerMarkerPositionOverride(const char* markerName, float x, float y, float z) {
    if (!g_markerControlsAvailable || !markerName || !markerName[0] ||
        !std::isfinite(x) || !std::isfinite(y) || !std::isfinite(z))
        return false;

    std::lock_guard<std::mutex> lock(g_playerMarkerOverrideMutex);
    PlayerMarkerPositionOverride* freeSlot = nullptr;
    for (auto& slot : g_playerMarkerOverrides) {
        if (slot.name[0] && _stricmp(slot.name, markerName) == 0) {
            slot.position[0] = x;
            slot.position[1] = y;
            slot.position[2] = z;
            slot.active = true;
            slot.dirty = true;
            g_playerMarkerOverridesPresent.store(true, std::memory_order_release);
            return true;
        }
        if (!slot.name[0] && !freeSlot) freeSlot = &slot;
    }
    if (!freeSlot) return false;

    strncpy_s(freeSlot->name, markerName, _TRUNCATE);
    freeSlot->position[0] = x;
    freeSlot->position[1] = y;
    freeSlot->position[2] = z;
    freeSlot->active = true;
    freeSlot->dirty = true;
    g_playerMarkerOverridesPresent.store(true, std::memory_order_release);
    Log::Detailf("Marker override: '%s' -> (%.3f, %.3f, %.3f)", markerName, x, y, z);
    return true;
}

bool ClearPlayerMarkerPositionOverride(const char* markerName) {
    if (!g_markerControlsAvailable || !markerName || !markerName[0]) return false;
    std::lock_guard<std::mutex> lock(g_playerMarkerOverrideMutex);
    for (auto& slot : g_playerMarkerOverrides) {
        if (!slot.name[0] || _stricmp(slot.name, markerName) != 0) continue;
        slot.active = false;
        slot.dirty = true;
        
        
        g_playerMarkerOverridesPresent.store(true, std::memory_order_release);
        return true;
    }
    
    return true;
}

