// ---- the Model Viewer's objects (model_viewer.cpp): the Birth Instance path, born where the viewer asks ----------
constexpr std::size_t kObjectBirthParamsFlagsOffset = 0x11C;   // ObjectInstanceBirthParams bits: m_initEffects (bit 0), ...
int ViewerPlayerStreamUnit() {
    void* player = CurrentPlayerInstance();
    return player ? int(*reinterpret_cast<const std::uint16_t*>(static_cast<const std::uint8_t*>(player) +
                                                                kInstanceBirthStreamUnitOffset))
                  : 0;
}
bool ViewerObjectsAvailable() {
    return g_instanceToolsAvailable && g_objectZoneLoadAndAddRef2 && g_objectZoneRelease2 && g_objectZoneIsLoaded &&
           g_objectInstanceBirthParamsCtor && g_birthObjectInstance && g_birthParamsSetPositionOverride &&
           g_instanceEnableRemoveThisFrame;
}
// As the Birth Instance tool: the name in the game's object list, its DRM in the mounted file systems.
const char* ViewerZoneId(const char* name, std::uint32_t& zoneId) {
    char resolved[128]{};
    bool unavailable = false;
    if (!ViewerObjectsAvailable()) return "the Birth Instance functions are not available";
    if (!ResolveBirthZone(name, zoneId, resolved, sizeof(resolved), unavailable))
        return unavailable ? "the game's object list is not loaded yet" : "not in the game's object list";
    char drmPath[260]{};
    if (!BuildObjectDrmPath(zoneId, resolved, drmPath, sizeof(drmPath))) return "no name to find its DRM by";
    auto** fsGlobal = At<FileSystemLite**>(kRvaGlobalFileSystem);
    if (!fsGlobal || !*fsGlobal || !(*fsGlobal)->vtable || !(*fsGlobal)->vtable->FileExists)
        return "the game's file system is not available";
    if (!EngineFileExists(drmPath)) return "its DRM is not in the game's archives";
    return nullptr;
}
bool ViewerZoneLoad(std::uint32_t zoneId, int priority) {
    return ViewerObjectsAvailable() && g_objectZoneLoadAndAddRef2(zoneId, true, nullptr, std::clamp(priority, 0, 5));
}
bool ViewerZoneLoaded(std::uint32_t zoneId) { return g_objectZoneIsLoaded && g_objectZoneIsLoaded(zoneId); }
void ViewerZoneRelease(std::uint32_t zoneId) {
    if (g_objectZoneRelease2) g_objectZoneRelease2(zoneId, true, nullptr);
}
void* ViewerBirth(std::uint32_t zoneId, int streamUnit, const float position[3]) {
    if (!ViewerObjectsAvailable()) return nullptr;
    alignas(16) std::array<std::uint8_t, kObjectInstanceBirthParamsSize> params{};
    g_objectInstanceBirthParamsCtor(params.data(), zoneId, streamUnit);
    // no birth effects (m_initEffects, bit 0 of +0x11C): as FrontEndObjectLoader's births for the relic viewer
    params[kObjectBirthParamsFlagsOffset] = std::uint8_t(params[kObjectBirthParamsFlagsOffset] & ~1u);
    if (position) {
        const Vec4 at{position[0], position[1], position[2], 1.0f};
        g_birthParamsSetPositionOverride(params.data(), &at);
    }
    void* born = g_birthObjectInstance(params.data());
    DestroyBirthParams(params.data());
    return born;
}
void ViewerRemove(void* instance) {
    if (instance && g_instanceEnableRemoveThisFrame) g_instanceEnableRemoveThisFrame(instance, false);
}

