bool MaterialEditorAvailable() { return g_materialEditorAvailable; }

void SetMaterialEditorActive(bool active) {
    if (!g_materialEditorAvailable) return;
    const bool wasActive = g_materialEditorActive.exchange(active, std::memory_order_acq_rel);
    if (!active) {
        g_materialConstantDragActive.store(false, std::memory_order_relaxed);
        g_materialHoverDesired.store(0, std::memory_order_release);
    }
    if (active && !wasActive) {
        g_materialForceRefresh.store(true, std::memory_order_release);   // (the list is rebuilt on opening)
        const auto state = g_materialEditorState.load(std::memory_order_acquire);
        if (state == MaterialEditorState::Unavailable)
            return;
        if (!g_materialResidentBuild.active && state == MaterialEditorState::Capturing)
            g_materialEditorState.store(MaterialEditorState::Idle, std::memory_order_release);
    }
}

