bool QueueMaterialConstantUpdate(std::uintptr_t materialAddress, int passIndex,
                                 int stage, std::uint32_t index, float value,
                                 bool finalize) {
    if (!g_materialEditorAvailable || !materialAddress || !std::isfinite(value) ||
        passIndex < 0 || passIndex >= 10 || stage < MaterialShaderStage_Pixel || stage > MaterialShaderStage_Domain)
        return false;
    
    
    if (g_materialDetailPublishedAddress.load(std::memory_order_acquire) != materialAddress) return false;
    g_materialConstantDragActive.store(!finalize, std::memory_order_relaxed);
    {
        std::lock_guard<std::mutex> lock(g_materialRequestMutex);
        QueuePendingMaterialEditLocked({MaterialEditType::Constant, materialAddress, passIndex, stage, index, value, 0, finalize});
    }
    g_hasPendingMaterialEdit.store(true, std::memory_order_release);
    g_materialEditorState.store(MaterialEditorState::UpdateQueued, std::memory_order_release);
    return true;
}

bool QueueMaterialTextureUpdate(std::uintptr_t materialAddress, int passIndex,
                                int stage, std::uint32_t entryIndex,
                                std::uintptr_t textureAddress) {
    if (!g_materialEditorAvailable || !materialAddress || passIndex < 0 || passIndex >= 10 ||
        stage < MaterialShaderStage_Pixel || stage > MaterialShaderStage_Domain)
        return false;
    if (!MaterialAddressPublished(materialAddress) || !IsKnownMaterialTexture(textureAddress)) return false;
    {
        std::lock_guard<std::mutex> lock(g_materialRequestMutex);
        QueuePendingMaterialEditLocked({MaterialEditType::Texture, materialAddress, passIndex, stage, entryIndex, 0.0f, textureAddress, true});
    }
    g_hasPendingMaterialEdit.store(true, std::memory_order_release);
    g_materialEditorState.store(MaterialEditorState::UpdateQueued, std::memory_order_release);
    return true;
}

