bool ForEachLiveModelInstance(void (*fn)(void* rmi, void* context), void* context) {
    if (!fn || !g_rmiTrackerAvailable.load(std::memory_order_acquire) || !g_rmiLive) return false;
    RmiTrackerLockGuard lock;
    for (void* rmi : *g_rmiLive) fn(rmi, context);
    return true;
}

bool SetHiddenModelParts(const std::vector<HiddenModelPart>& parts) {
    if (!g_rmiTrackerAvailable.load(std::memory_order_acquire) || !MaterialResourceVisibilityAvailable()) return false;
    std::unordered_map<std::uint64_t, HiddenPartModel> next;
    std::vector<std::uint32_t> counts;
    std::size_t hidden = 0;
    for (const HiddenModelPart& p : parts) {
        if (!p.parts || p.parts > 4096 || p.part >= p.parts) continue;
        HiddenPartModel& model = next[p.layout];
        if (model.parts && model.parts != p.parts) continue;   // (one layout, one part count)
        model.parts = p.parts;
        model.bits.resize((p.parts + 63u) / 64u);
        const std::uint64_t bit = 1ull << (p.part & 63u);
        if (!(model.bits[p.part >> 6] & bit)) ++hidden;
        model.bits[p.part >> 6] |= bit;
        counts.push_back(p.parts);
    }
    std::sort(counts.begin(), counts.end());
    counts.erase(std::unique(counts.begin(), counts.end()), counts.end());
    const std::size_t models = next.size();
    {
        RmiTrackerLockGuard lock;
        if (!g_hiddenParts) g_hiddenParts = new std::unordered_map<std::uint64_t, HiddenPartModel>();
        if (!g_hiddenPartCounts) g_hiddenPartCounts = new std::vector<std::uint32_t>();
        *g_hiddenParts = std::move(next);
        *g_hiddenPartCounts = std::move(counts);
        g_hiddenPartModels.store(static_cast<std::uint32_t>(models), std::memory_order_relaxed);
    }
    g_hiddenPartsChanged.store(true, std::memory_order_release);
    Log::Detailf("Part visibility: %zu part(s) of %zu model(s) to hide", hidden, models);
    return true;
}

bool SetMaterialResourceHiddenOne(std::uint32_t resourceId, bool hidden);

// A material of a custom outfit's mod whose ID the game uses elsewhere was given a new ID (CustomOutfits): hiding the
// original ID hides the outfit's copy too, so scripts written for the mod keep working in the outfit's own slot.
bool SetMaterialResourceHidden(std::uint32_t resourceId, bool hidden) {
    const bool ok = SetMaterialResourceHiddenOne(resourceId, hidden);
    std::vector<std::uint32_t> renamed(2048);   // (one per outfit at most; 8 before 0.9.404)
    const int count = CustomOutfits::RenamedMaterialIds(resourceId, renamed.data(), static_cast<int>(renamed.size()));
    for (int i = 0; i < count; ++i) SetMaterialResourceHiddenOne(renamed[static_cast<std::size_t>(i)], hidden);
    return ok;
}

bool SetMaterialResourceHiddenOne(std::uint32_t resourceId, bool hidden) {
    if (!MaterialResourceVisibilityAvailable() || resourceId == 0) return false;
    HiddenMaterialResourceSlot* slot = FindHiddenMaterialResourceSlot(resourceId, hidden);
    if (!slot) return !hidden;

    const bool previous = slot->hidden.exchange(hidden, std::memory_order_acq_rel);
    if (previous == hidden) return true;

    g_materialResourceSuppressedDrawCount.store(0, std::memory_order_relaxed);
    slot->applyRequested.store(true, std::memory_order_release);
    if (hidden) {
        g_materialHiddenResourceCount.fetch_add(1, std::memory_order_relaxed);
        Log::Detailf("Material visibility: hiding material ID %u (0x%08X) through resident CommonMaterial pointer matching",
                    resourceId, resourceId);
    } else {
        if (g_materialHiddenResourceCount.load(std::memory_order_relaxed) != 0)
            g_materialHiddenResourceCount.fetch_sub(1, std::memory_order_relaxed);
        Log::Detailf("Material visibility: showing material ID %u (0x%08X) through resident CommonMaterial pointer matching",
                    resourceId, resourceId);
    }
    return true;
}

bool ToggleMaterialResourceHidden(std::uint32_t resourceId, bool& hiddenNow) {
    hiddenNow = false;
    if (!MaterialResourceVisibilityAvailable() || resourceId == 0) return false;
    const bool target = !IsMaterialResourceHiddenFast(resourceId);
    if (!SetMaterialResourceHidden(resourceId, target)) return false;
    hiddenNow = target;
    return true;
}

