bool RequestBirthInstanceAt(const char* objectNameOrZoneId, const PlayerTransform& transform) {
    if (!BirthAtTransformAvailable()) return false;
    for (float v : transform.position) if (!std::isfinite(v)) return false;
    for (float v : transform.rotation) if (!std::isfinite(v)) return false;
    if (!RequestBirthInstance(objectNameOrZoneId)) return false;
    std::lock_guard<std::mutex> lock(g_birthInstanceMutex);
    g_birthTarget = transform;
    g_birthAtTarget = true;
    return true;
}

