const char* BirthInstanceStatus() {
    switch (g_birthInstanceState.load(std::memory_order_relaxed)) {
        case BirthInstanceState::Unavailable: return "Unavailable";
        case BirthInstanceState::Ready: return "";   // (v1.0.0: no "Ready" line)
        case BirthInstanceState::Queued: return "Queued for gameplay thread";
        case BirthInstanceState::ValidatingDrm: return "Checking ObjectZone DRM...";
        case BirthInstanceState::Loading: return "Loading ObjectZone...";
        case BirthInstanceState::Birthing: return "Birthing instance...";
        case BirthInstanceState::Success:   // (v1.0.0: for 3 s after the birth, then no line)
            return GetTickCount64() - g_birthSuccessMs.load(std::memory_order_relaxed) < 3000 ? "Instance birthed successfully" : "";
        case BirthInstanceState::FailedName: return "Unknown ObjectZone name";
        case BirthInstanceState::FailedZoneTable: return "Embedded ObjectZone table unavailable (numeric zone IDs still work)";
        case BirthInstanceState::FailedDrmValidation: return "Birth cancelled: unable to validate this ObjectZone's DRM";
        case BirthInstanceState::FailedMissingDrm: return "Birth cancelled: this ObjectZone has no loadable DRM";
        case BirthInstanceState::FailedLoad: return "ObjectZone load failed or timed out";
        case BirthInstanceState::FailedNoContext: return "No valid player/stream context";
        case BirthInstanceState::FailedBirth: return "BirthObjectInstance returned null";
    }
    return "Unknown";
}

