int FindZoneSuggestions(const char* queryText, Features::ZoneSuggestion* out, int capacity) {
    if (!out || capacity <= 0 || !queryText || !queryText[0]) return 0;
    EnsureZoneListLoaded();
    if (!g_zoneListLoaded) return 0;

    std::string query = NormalizeZoneName(queryText);
    if (query.empty()) return 0;
    if (query.rfind("zone:", 0) == 0) {
        query.erase(0, 5);
        const auto first = query.find_first_not_of(" \t");
        if (first == std::string::npos) return 0;
        query.erase(0, first);
    }

    struct Candidate {
        int score;
        std::uint32_t id;
    };
    std::vector<Candidate> candidates;
    candidates.reserve(256);

    const bool numericQuery = std::all_of(query.begin(), query.end(), [](unsigned char c) {
        return std::isdigit(c) != 0;
    });

    for (std::uint32_t id = 1; id < g_zoneNameById.size(); ++id) {
        if (g_zoneNameById[id].empty()) continue;
        int score = std::numeric_limits<int>::max();
        if (numericQuery) {
            const std::string idText = std::to_string(id);
            if (idText == query) score = 0;
            else if (idText.rfind(query, 0) == 0)
                score = 100 + static_cast<int>(idText.size() - query.size());
        } else {
            const std::string normalizedName = NormalizeZoneName(g_zoneNameById[id].c_str());
            score = ZoneSuggestionScore(normalizedName, query);
        }
        if (score != std::numeric_limits<int>::max())
            candidates.push_back({score, id});
    }

    std::sort(candidates.begin(), candidates.end(), [](const Candidate& a, const Candidate& b) {
        if (a.score != b.score) return a.score < b.score;
        return a.id < b.id;
    });

    const int count = std::min(capacity, static_cast<int>(candidates.size()));
    for (int i = 0; i < count; ++i) {
        out[i] = {};
        out[i].zoneId = candidates[static_cast<std::size_t>(i)].id;
        strncpy_s(out[i].name, g_zoneNameById[out[i].zoneId].c_str(), _TRUNCATE);
    }
    return count;
}

