float TimeScale() {
    if (!g_timeControlsAvailable) return 1.0f;
    if (g_timeScaleOverrideActive.load(std::memory_order_relaxed))
        return g_timeScaleOverride.load(std::memory_order_relaxed);
    if (!g_timeManagerGetTimeMult) return 1.0f;
    void* manager = CurrentTimeManager();
    return manager ? g_timeManagerGetTimeMult(manager) : 1.0f;
}
bool SetTimeScale(float value) {
    if (!g_timeControlsAvailable || !g_timeManagerSetTimeMult) return false;
    value = std::clamp(value, 0.05f, 4.0f);
    g_timeScaleOverride.store(value, std::memory_order_relaxed);
    g_timeScaleOverrideActive.store(std::fabs(value - 1.0f) > 0.0001f, std::memory_order_relaxed);
    if (void* manager = CurrentTimeManager())
        g_timeManagerSetTimeMult(manager, value);
    return true;
}

