const char* WeatherStatus() {
    if (!g_gameplayDispatchAvailable ||
        !g_weatherAvailable.load(std::memory_order_relaxed))
        return "Unavailable for this executable build";

    switch (g_weatherRuntimeStatus.load(std::memory_order_acquire)) {
        case WeatherRuntimeStatus::WaitingForGlobalWeather:
            return "Waiting for GlobalWeather data";
        case WeatherRuntimeStatus::WaitingForCatalog:
            return "Waiting for authored weather/time-of-day catalog";
        case WeatherRuntimeStatus::WaitingForManager:
            return "Waiting for WeatherManager singleton";
        case WeatherRuntimeStatus::WaitingForWeatherArray:
            return "WeatherManager created; waiting for weather runtime array";
        case WeatherRuntimeStatus::WaitingForTimeOfDay:
            return "WeatherManager created; waiting for active time-of-day";
        case WeatherRuntimeStatus::Ready:
            break;
    }

    const bool anyOverride =
        g_precipitationOverride.load(std::memory_order_relaxed) ||
        g_timeOfDayOverride.load(std::memory_order_relaxed);
    return anyOverride ? "Ready - override active" : "Ready - game controlled";
}

