bool GetPlayerTransform(PlayerTransform& out) {
    return ReadTransform(out);
}

bool TeleportPlayer(const PlayerTransform& transform) {
    if (!g_teleportAvailable) return false;
    void* player = CurrentPlayer();
    if (!player) return false;

    PlayerTransform current{};
    Vec4 currentRaw{};
    if (!ReadTransform(current, &currentRaw)) return false;

    Vec4 position{
        transform.position[0], transform.position[1], transform.position[2],
        currentRaw.w
    };
    Euler rotation{transform.rotation[0], transform.rotation[1], transform.rotation[2]};
    g_teleportPlayer(player, &position, &rotation);
    return true;
}

bool QueuePlayerTransform(const PlayerTransform& transform) {
    if (!g_teleportAvailable || OutfitSwapInProgress()) return false;
    for (float v : transform.position) if (!std::isfinite(v)) return false;
    for (float v : transform.rotation) if (!std::isfinite(v)) return false;

    std::lock_guard<std::mutex> lock(g_playerTransformMutex);
    
    
    g_pendingPlayerTransform.pending = true;
    g_pendingPlayerTransform.transform = transform;
    g_hasPendingPlayerTransform.store(true, std::memory_order_release);
    return true;
}

