int CopyDrawInstances(DrawInstanceLabel* out, int capacity) {
    if (!out || capacity <= 0) return 0;
    std::lock_guard<std::mutex> lock(g_drawMutex);
    const int count = std::min<int>(capacity, static_cast<int>(g_drawInstanceSnapshot.size()));
    if (count) std::memcpy(out, g_drawInstanceSnapshot.data(), static_cast<std::size_t>(count) * sizeof(DrawInstanceLabel));
    return count;
}

