const char* DrawToolsStatus() {
    if (!DrawToolsAvailable()) return "Unavailable for this executable build";
    if (!g_markupDrawVerified) return "Available (Draw markup: unavailable for this executable build)";
    return "Available";
}

const char* DrawMarkupTypeName(int type) {
    // MarkupDetectionUtils::MarkupTypeToName (20..22 have no name there)
    static const char* const kNames[] = {
        "None", "LedgeGrab", "JumpLanding", "EnemyDropdown", "Pole", "VerticalPole", "HorizontalPole", "Zipline",
        "RailSlide", "Ladder", "Water", "Rope", "CrouchCover", "StandingCover", "Perch", "BalanceBeam", "Pillar",
        "VehicleJumpTarget", "ConstrainedGround", "EdgeStop", "Unknown", "Unknown", "Unknown", "TreeClimb",
        "TreeScramble", "DefaultPolyLine"};
    return type >= 0 && type < static_cast<int>(sizeof(kNames) / sizeof(kNames[0])) ? kNames[type] : "Unknown";
}

const char* DrawInstancesStatus() {
    static thread_local char text[160];
    if (!DrawInstances()) return "";
    std::snprintf(text, sizeof(text), "%d Instances within %.0f m", DrawInstanceCount(),
                  g_drawInstancesDistance.load(std::memory_order_relaxed) / 100.0f);
    return text;
}

const char* DrawTriggersStatus() {
    static thread_local char text[160];
    if (!DrawTriggers()) return "";
    std::snprintf(text, sizeof(text), "%d trigger volumes (all loaded ones)", DrawTriggerCount());
    return text;
}

const char* DrawMarkupStatus() {
    static thread_local char text[256];
    if (!DrawMarkup()) return "";
    MarkupPassStats pass{};
    double passMs = 0.0;
    int lines = 0;
    {
        std::lock_guard<std::mutex> lock(g_drawMutex);
        pass = g_markupPublished;
        passMs = g_markupPublishedPassMs;
        lines = static_cast<int>(g_drawMarkupSnapshot.size());
    }
    if (!pass.visited) {
        std::snprintf(text, sizeof(text), "scanning the markup...");
        return text;
    }
    std::snprintf(text, sizeof(text), "%d lines from %u boxes in range (%u boxes loaded; last scan %.1f ms)", lines,
                  pass.drawn, pass.visited, passMs);
    return text;
}

bool Invulnerability() { return g_invulnerability.load(std::memory_order_relaxed); }
void SetInvulnerability(bool value) {
    if (!g_invulnerabilityAvailable) return;
    const bool previous = g_invulnerability.exchange(value, std::memory_order_relaxed);
    if (previous == value) return;

    void* health = CurrentHealth();
    if (value) {
        if (health) {
            g_setInvincibleInt(health, -1);
            g_lastInvincibleHealth = health;
        }
        Log::Detail("Player: invulnerability enabled");
    } else {
        if (health) g_setInvincibleInt(health, 0);
        
        
        
        g_lastInvincibleHealth = nullptr;
        Log::Detail("Player: invulnerability disabled");
    }
}

bool OneHitKill() { return g_oneHitKill.load(std::memory_order_relaxed); }
void SetOneHitKill(bool value) {
    if (value && !g_oneHitKillAvailable) value = false;
    const bool previous = g_oneHitKill.exchange(value, std::memory_order_acq_rel);
    g_oneHitKillPlayerHealth.store(0, std::memory_order_release);
    if (previous != value)
        Log::Detail(value ? "Player: One Hit Kill enabled" : "Player: One Hit Kill disabled");
}

