// Instance +0x80, false), retail 0x334E10, TR2 0x357400, as Instance::InitComponents_Generic calls it).
constexpr std::uintptr_t kRvaGearFxEnd = 0x00323FC0ull, kRvaGearFxTriggerInit = 0x00334E10ull,
                         kRvaGearGetFxComponent = 0x003DE6F0ull;
